    toDate(block_date)                    AS date,
    upper(symbol)                         AS symbol,
    anyLast(coingecko_id)                 AS coingecko_id,
    anyLast(toFloat64(price))             AS price
FROM {{ source('crawlers_data_external_prices', 'coingecko_prices') }}
GROUP BY date, symbol
