{{ 
    config(
        materialized='incremental',
        incremental_strategy='insert_overwrite',
        engine='ReplacingMergeTree()',
        order_by='(date, bticker)',
        partition_by='toStartOfMonth(date)',
        pre_hook=[
            "SET max_memory_usage = 6000000000",
            "SET max_bytes_before_external_group_by = 2000000000"
        ],
        post_hook=[
            "SET max_memory_usage = 0",
            "SET max_bytes_before_external_group_by = 0"
        ],
        tags=['production','execution','rwa','backedfi','prices']
    )
}}


{% set btickers = [
    'bC3M',
    'bCOIN',
    'bCSPX',
    'bHIGH',
    'bIB01',
    'bIBTA',
    'bMSTR',
    'bNVDA',
    'TSLAx'
] %}

{% set sql_queries = [] %}

{% for bticker in btickers %}
    {% set model_name = 'contracts_backedfi_' + bticker + '_Oracle_events' %}
    {% set sql %}
        SELECT
            '{{ bticker }}' as bticker
            ,toStartOfDay(block_timestamp) AS date
            ,argMax(toUInt256OrNull(decoded_params['current'])/POWER(10,8),block_timestamp) AS price
        FROM {{ ref(model_name) }}
        WHERE
            event_name = 'AnswerUpdated'
            AND block_timestamp < today()
            {% if var('start_month', none) and var('end_month', none) %}
                AND toStartOfMonth(toDate(block_timestamp)) >= toDate('{{ var("start_month") }}')
                AND toStartOfMonth(toDate(block_timestamp)) <= toDate('{{ var("end_month") }}')
            {% else %}
                {{ apply_monthly_incremental_filter('block_timestamp', 'date', 'true') }}
            {% endif %}
        GROUP BY 1, 2
    {% endset %}
    {% do sql_queries.append(sql) %}
{% endfor %}

{{ sql_queries | join('\nunion all\n') }}

model.gnosis_dbt.fct_execution_rwa_backe.raw_code:
{{ 
    config(
        materialized='view',
        tags=['production','execution','rwa','backedfi','prices']
    )
}}

{% set btickers = [
  'bC3M','bCOIN','bCSPX','bHIGH',
  'bIB01','bIBTA','bMSTR','bNVDA','TSLAx'
] %}

{% set fill_start = "2020-01-01" %}   -- safely before any token was listed
{% set unions = [] %}

{% for b in btickers %}
{% set sql %}
SELECT
  bticker,
  date,
  price
FROM (
    /* gather sparse rows, fill, forward-fill */
    SELECT
      '{{ b }}'       AS bticker,
      date,
      /* forward-fill price */
      last_value(price) IGNORE NULLS
        OVER (
          ORDER BY date
          ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW
        ) AS price
    FROM (
        /* sparse daily data for this one ticker */
        SELECT
          toDate(date)            AS date,
          max(price)              AS price          -- one value per day
        FROM {{ ref('int_execution_rwa_backedfi_prices') }}
        WHERE bticker = '{{ b }}'
        GROUP BY date
        ORDER BY date
          WITH FILL
            FROM toDate('{{ fill_start }}')
            TO today()
            STEP 1
    )
)
WHERE price IS NOT NULL AND date < today()       -- drop rows before first real point
{% endset %}
{% do unions.append(sql) %}
{% endfor %}

{{ unions | join('\nUNION ALL\n') }}
ORDER BY bticker, date

