model.gnosis_dbt.int_execution_pools_dex.raw_code:
{{
    config(
        materialized='incremental',
        incremental_strategy='insert_overwrite',
        engine='ReplacingMergeTree()',
        order_by='(block_timestamp, transaction_hash)',
        partition_by='toStartOfMonth(block_timestamp)',
        settings={'allow_nullable_key': 1},
        tags=['production', 'execution', 'pools', 'trades', 'intermediate']
    )
}}

{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

SELECT DISTINCT
    t.block_timestamp,
    t.transaction_hash,
    lower(t.from_address) AS tx_from,
    lower(t.to_address)   AS tx_to
FROM {{ source('execution', 'transactions') }} t
WHERE t.transaction_hash IN (
    SELECT DISTINCT transaction_hash
    FROM {{ ref('int_execution_pools_dex_trades_raw') }}
    {% if start_month and end_month %}
    WHERE toStartOfMonth(block_timestamp) >= toDate('{{ start_month }}')
      AND toStartOfMonth(block_timestamp) <= toDate('{{ end_month }}')
    {% else %}
      {{ apply_monthly_incremental_filter('block_timestamp', 'block_timestamp') }}
    {% endif %}
)
{% if start_month and end_month %}
AND t.block_timestamp >= toDate('{{ start_month }}') - INTERVAL 1 DAY
AND t.block_timestamp <= toDate('{{ end_month }}') + INTERVAL 32 DAY
{% else %}
  {# Whole-month rebuild: the IN-list (trades_raw) returns COMPLETE months under
     insert_overwrite, so this transactions filter must cover the same months. A
     day-level (max-3) bound left most of the rebuilt month with NULL tx_from. #}
  {{ apply_monthly_incremental_filter('t.block_timestamp', 'block_timestamp', add_and=True) }}
{% endif %}

{{
    config(
        materialized='incremental',
        incremental_strategy='insert_overwrite',
        engine='ReplacingMergeTree()',
        order_by='(block_timestamp, transaction_hash, log_index)',
        partition_by='toStartOfMonth(block_timestamp)',
        settings={'allow_nullable_key': 1},
        pre_hook=[
            "SET max_threads = 1",
            "SET max_block_size = 8192",
            "SET max_bytes_before_external_group_by = 2000000000",
            "SET max_bytes_before_external_sort = 2000000000"
        ],
        post_hook=[
            "SET max_threads = 0",
            "SET max_block_size = 65505",
            "SET max_bytes_before_external_group_by = 0",
            "SET max_bytes_before_external_sort = 0"
        ],
        tags=['production', 'execution', 'pools', 'trades', 'intermediate']
    )
}}

{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

WITH

swaps AS (
    SELECT
        s.*,
        tx.tx_from,
        tx.tx_to
    FROM (
        SELECT *
        FROM {{ ref('int_execution_pools_dex_trades_raw') }}
        {% if start_month and end_month %}
        WHERE toStartOfMonth(block_timestamp) >= toDate('{{ start_month }}')
          AND toStartOfMonth(block_timestamp) <= toDate('{{ end_month }}')
        {% else %}
          {{ apply_monthly_incremental_filter('block_timestamp', 'block_timestamp') }}
        {% endif %}
    ) s
    LEFT JOIN (
        SELECT transaction_hash, tx_from, tx_to
        FROM {{ ref('int_execution_pools_dex_trades_tx_context') }}
        {% if start_month and end_month %}
        WHERE toStartOfMonth(block_timestamp) >= toDate('{{ start_month }}')
          AND toStartOfMonth(block_timestamp) <= toDate('{{ end_month }}')
        {% else %}
          {# Whole-month rebuild: tx_context returns COMPLETE months under
             insert_overwrite; a day-level (max-3) bound dropped tx_from/tx_to for
             most of the rebuilt month and broke the coalesce(taker, tx_from). #}
          {{ apply_monthly_incremental_filter('block_timestamp', 'block_timestamp') }}
        {% endif %}
    ) tx ON tx.transaction_hash = s.transaction_hash
),

with_bought_price AS (
    SELECT
        s.*,
        pb.price AS token_bought_price_usd
    FROM swaps s
    ASOF LEFT JOIN (
        SELECT symbol, date, price
        FROM {{ ref('int_execution_token_prices_daily') }}
        {% if start_month and end_month %}
        WHERE date BETWEEN toDate('{{ start_month }}') - INTERVAL 30 DAY
                       AND toDate('{{ end_month }}') + INTERVAL 32 DAY
        {% else %}
          {# Whole-month rebuild: cover the rebuilt month plus a price runway so
             ASOF can still find a prior price for early-month trades. Honors the
             price_lookback_days refill var like other price consumers. #}
          {{ apply_monthly_incremental_filter('date', 'block_timestamp', lookback_days=31) }}
        {% endif %}
        ORDER BY symbol, date
    ) pb
        ON  pb.symbol                 = s.token_bought_symbol
        AND toDate(s.block_timestamp) >= pb.date
),

with_sold_price AS (
    SELECT
        s.*,
        ps.price AS token_sold_price_usd
    FROM with_bought_price s
    ASOF LEFT JOIN (
        SELECT symbol, date, price
        FROM {{ ref('int_execution_token_prices_daily') }}
        {% if start_month and end_month %}
        WHERE date BETWEEN toDate('{{ start_month }}') - INTERVAL 30 DAY
                       AND toDate('{{ end_month }}') + INTERVAL 32 DAY
        {% else %}
          {# Whole-month rebuild: cover the rebuilt month plus a price runway so
             ASOF can still find a prior price for early-month trades. Honors the
             price_lookback_days refill var like other price consumers. #}
          {{ apply_monthly_incremental_filter('date', 'block_timestamp', lookback_days=31) }}
        {% endif %}
        ORDER BY symbol, date
    ) ps
        ON  ps.symbol                 = s.token_sold_symbol
        AND toDate(s.block_timestamp) >= ps.date
)

SELECT
    block_number,
    block_timestamp,
    transaction_hash,
    log_index,
    protocol,
    pool_address,
    token_bought_address,
    token_bought_symbol,
    amount_bought_raw,
    amount_bought,
    token_sold_address,
    token_sold_symbol,
    amount_sold_raw,
    amount_sold,
    COALESCE(
        amount_bought * token_bought_price_usd,
        amount_sold   * token_sold_price_usd
    )                   AS amount_usd,
    coalesce(taker, tx_from) AS taker,
    tx_from,
    tx_to
FROM with_sold_price

