model.gnosis_dbt.int_execution_safes.raw_code:
{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

{{
  config(
    materialized='incremental',
    incremental_strategy='insert_overwrite',
    engine='ReplacingMergeTree()',
    order_by='(safe_address)',
    partition_by='toStartOfMonth(block_timestamp)',
    settings={ 'allow_nullable_key': 1 },
    tags=['production','execution','safe'],
    pre_hook=["SET join_algorithm = 'grace_hash'"],
    post_hook=["SET join_algorithm = 'default'"]
  )
}}
{% set traces_pre_filter %}
    action_call_type = 'delegate_call'
    AND result_gas_used > 10000
    AND lower(substring(action_input, 1, 8)) IN ('0ec78d9e','a97ab18a','b63e800d')
    AND lower(action_to) IN (
        SELECT lower(replaceAll(address, '0x', '')) FROM {{ ref('safe_singletons') }}
    )
    AND block_timestamp >= toDateTime('2020-05-21')
    {% if start_month and end_month %}
      AND toStartOfMonth(toDate(block_timestamp)) >= toDate('{{ start_month }}')
      AND toStartOfMonth(toDate(block_timestamp)) <= toDate('{{ end_month }}')
    {% else %}
      {{ apply_monthly_incremental_filter('block_timestamp', 'block_timestamp', add_and=True) }}
    {% endif %}
{% endset %}

WITH traces AS (
    {{ dedup_source(
        source_ref   = source('execution','traces'),
        partition_by = 'block_number, transaction_hash, trace_address',
        columns      = 'action_from, action_to, action_input, action_call_type, result_gas_used, block_timestamp, block_number, transaction_hash',
        pre_filter   = traces_pre_filter
    ) }}
),

singletons AS (
    -- Match the trace storage format: lowercase hex, NO 0x prefix.
    SELECT
        lower(replaceAll(address, '0x', ''))        AS singleton_address,
        version,
        is_l2,
        lower(replaceAll(setup_selector, '0x', '')) AS setup_selector
    FROM {{ ref('safe_singletons') }}
)

SELECT
    -- Re-prefix outputs so downstream models get the canonical 0x... shape.
    concat('0x', lower(tr.action_from))              AS safe_address,
    sg.version                                       AS creation_version,
    sg.is_l2                                         AS is_l2,
    concat('0x', lower(tr.action_to))                AS creation_singleton,
    toDate(tr.block_timestamp)                       AS block_date,
    tr.block_timestamp                               AS block_timestamp,
    tr.block_number                                  AS block_number,
    concat('0x',tr.transaction_hash)                 AS tx_hash,
    tr.result_gas_used                               AS gas_used
FROM traces tr
INNER JOIN singletons sg
    ON lower(tr.action_to) = sg.singleton_address
   AND lower(substring(tr.action_input, 1, 8)) = sg.setup_selector

model.gnosis_dbt.api_execution_account_s.raw_code:
{{
    config(
        materialized='view',
        tags=["production", "execution", "safe", "tier2", "api:account_safes", "granularity:latest"],
        meta={
            "api": {
                "methods": ["GET", "POST"],
                "allow_unfiltered": false,
                "require_any_of": ["owner_address"],
                "parameters": [
                    {
                        "name": "owner_address",
                        "column": "owner_address",
                        "operator": "=",
                        "type": "string",
                        "case": "lower",
                        "description": "Address whose owned Safes we want to list"
                    }
                ],
                "pagination": {
                    "enabled": true,
                    "default_limit": 500,
                    "max_limit": 5000,
                    "response": "envelope"
                },
                "sort": [
                    {"column": "became_owner_at", "direction": "DESC"}
                ],
                "sortable_fields": ["owner_address", "safe_address", "became_owner_at", "current_threshold", "current_owner_count", "deployment_date"]
            }
        }
    )
}}

SELECT sub.*, (SELECT toDate(max(block_date)) FROM {{ ref('int_execution_safes') }}) AS as_of_date
FROM (
-- Reverse lookup: "which Safes does this address own?" One row per
-- (owner, safe) pair enriched with that safe's threshold, owner count, and
-- deployment date so the Account Portfolio Safe section can render a full
-- table in a single round-trip.
--
-- Note: the filter column is `owner_address` so the same account search
-- input can cascade directly; the caller doesn't need to know the schema
-- of the underlying intermediate.
SELECT
    owner_address,
    safe_address,
    became_owner_at,
    current_threshold,
    current_owner_count,
    creation_version,
    deployment_date
FROM {{ ref('fct_execution_account_safes_latest') }}
) AS sub

model.gnosis_dbt.api_execution_safes_cur.raw_code:
{{
    config(
        materialized='view',
        tags=["production", "execution", "safe", "tier2", "api:safes_current_owners", "granularity:latest"],
        meta={
            "api": {
                "methods": ["GET", "POST"],
                "allow_unfiltered": false,
                "require_any_of": ["safe_address", "owner_address"],
                "parameters": [
                    {
                        "name": "safe_address",
                        "column": "safe_address",
                        "operator": "=",
                        "type": "string",
                        "case": "lower",
                        "description": "Safe contract address — returns every current owner of this Safe"
                    },
                    {
                        "name": "owner_address",
                        "column": "owner_address",
                        "operator": "=",
                        "type": "string",
                        "case": "lower",
                        "description": "Owner (EOA or contract) address — returns every Safe this address currently owns"
                    }
                ],
                "pagination": {
                    "enabled": true,
                    "default_limit": 500,
                    "max_limit": 5000,
                    "response": "envelope"
                },
                "sort": [
                    {"column": "became_owner_at", "direction": "DESC"}
                ],
                "sortable_fields": ["safe_address", "owner_address", "became_owner_at"]
            }
        }
    )
}}

SELECT sub.*, (SELECT toDate(max(block_timestamp)) FROM {{ ref('int_execution_safes_owner_events') }}) AS as_of_date
FROM (
-- Per-Safe current owners (add-only snapshot from the owner-events log).
-- One row per (safe, owner) pair where the last observed event for that pair
-- is `safe_setup` or `added_owner`. Matches the shape of every other latest
-- snapshot view: filter supported on either side of the relationship so the
-- Account Portfolio tab can query "who owns this safe?" and "which safes
-- does this address own?" against the same view.
--
-- Renaming `owner` → `owner_address` so the API filter parameter name reads
-- naturally. `current_threshold` surfaces here too so callers don't need a
-- second query to render "M of N signatures" — the threshold is constant
-- per safe and denormalising it per owner row avoids an extra join.
SELECT
    safe_address,
    owner AS owner_address,
    became_owner_at,
    current_threshold
FROM {{ ref('int_execution_safes_current_owners') }}
) AS sub

model.gnosis_dbt.int_execution_transacti.raw_code:
{{
  config(
    materialized='incremental',
    incremental_strategy='append',
    engine='ReplacingMergeTree()',
    order_by='address_hash',
    settings={'allow_nullable_key': 1},
    tags=['production','execution','transactions']
  )
}}

{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month', none) %}

{% set txn_pre_filter %}
    block_timestamp < today()
    AND from_address IS NOT NULL
    AND success = 1
    {% if start_month and end_month %}
      AND toStartOfMonth(block_timestamp) >= toDate('{{ start_month }}')
      AND toStartOfMonth(block_timestamp) <= toDate('{{ end_month }}')
    {% elif is_incremental() %}
      AND toStartOfMonth(block_timestamp) >= (
        SELECT toStartOfMonth(max(first_seen_date))
        FROM {{ this }}
      )
    {% endif %}
{% endset %}

WITH deduped_transactions AS (
    SELECT
        block_timestamp,
        CONCAT('0x', from_address) AS from_address
    FROM (
        {{ dedup_source(
            source_ref=source('execution', 'transactions'),
            partition_by='block_number, transaction_index',
            columns='block_timestamp, from_address',
            pre_filter=txn_pre_filter
        ) }}
    )
),

new_addresses AS (
    SELECT
        cityHash64(lower(from_address)) AS address_hash,
        min(toDate(block_timestamp))    AS first_seen_date
    FROM deduped_transactions
    GROUP BY address_hash
)

SELECT
    address_hash,
    first_seen_date
FROM new_addresses

{{
  config(
    materialized='incremental',
    incremental_strategy='insert_overwrite',
    engine='ReplacingMergeTree()',
    order_by='(project, month)',
    partition_by='toStartOfMonth(month)',
    tags=['production','execution','transactions']
  )
}}

{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month', none) %}

WITH src AS (
  SELECT
    toStartOfMonth(date)                   AS month,
    project,
    sumState(tx_count)                     AS txs_state,
    sumState(fee_native_sum)               AS fee_state,
    groupBitmapMergeState(ua_bitmap_state) AS aa_state
  FROM {{ ref('int_execution_transactions_by_project_daily') }}
  WHERE 1=1
    {% if start_month and end_month %}
      AND toStartOfMonth(date) >= toDate('{{ start_month }}')
      AND toStartOfMonth(date) <= toDate('{{ end_month }}')
    {% else %}
      {{ apply_monthly_incremental_filter('date', 'month', 'true') }}
    {% endif %}
  GROUP BY month, project
)

SELECT project, month, txs_state, fee_state, aa_state
FROM src

