model.gnosis_dbt.int_revenue_fees_monthl.raw_code:
{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

{# Partition grain MUST equal the insert_overwrite grain. This model is
   rebuilt in monthly windows; the previous toStartOfYear(month) partition
   made every incremental run replace the WHOLE year partition with only
   the lookback months, silently deleting all other months of that year
   (observed 2026-06: only Apr-May 2026 and Oct-Dec of prior years
   survived). Monthly partitions stay far below the ClickHouse Cloud
   100-partitions-per-insert cap even on a full-history rebuild. #}
{{
  config(
    materialized='incremental',
    incremental_strategy='insert_overwrite',
    engine='ReplacingMergeTree()',
    order_by='(month, stream_type, symbol, user)',
    partition_by='month',
    settings={'allow_nullable_key': 1},
    tags=['production','revenue','revenue_cross']
  )
}}

-- Reads the unified view (single canonicalization junction for the June
-- 2026 Safe migration) instead of re-unioning the stream models, so the
-- per-user key here always matches the cross-stream canonical address.
WITH daily AS (
    SELECT stream_type, date, user, symbol, fees
    FROM {{ ref('int_revenue_fees_unified_daily') }}
)

SELECT
    toStartOfMonth(date) AS month,
    stream_type,
    user,
    symbol,
    round(sum(fees), 8) AS month_fees
FROM daily
WHERE toStartOfMonth(date) < toStartOfMonth(today())
  {% if start_month and end_month %}
    AND toStartOfMonth(date) >= toDate('{{ start_month }}')
    AND toStartOfMonth(date) <= toDate('{{ end_month }}')
  {% else %}
    {{ apply_monthly_incremental_filter('date', 'month', true, lookback_days=2, lookback_res='month') }}
  {% endif %}
GROUP BY month, stream_type, user, symbol

model.gnosis_dbt.int_revenue_active_user.raw_code:
{% set active_threshold_usd = 0.5 %}
{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

{#
  Same shape as int_revenue_active_users_totals_weekly: cron runs recompute
  complete month partitions via insert_overwrite with the same 2-month
  lookback the upstream (int_revenue_fees_monthly_per_user) uses for its own
  restatement window. Strategy resolves to `append` when start_month is set
  so refresh.py stages append non-overlapping windows instead of REPLACE
  PARTITION wiping earlier stages
  (docs/lessons/staged-insert-overwrite-wipe.md).
#}
{{
  config(
    materialized='incremental',
    incremental_strategy=('append' if start_month else 'insert_overwrite'),
    engine='ReplacingMergeTree()',
    order_by='(month)',
    partition_by='month',
    pre_hook=[
        "SET max_bytes_before_external_group_by = 2000000000",
        "SET max_bytes_before_external_sort = 2000000000"
    ],
    post_hook=[
        "SET max_bytes_before_external_group_by = 0",
        "SET max_bytes_before_external_sort = 0"
    ],
    tags=['production','revenue','revenue_cross']
  )
}}

WITH per_user AS (
    SELECT
        month,
        user,
        sum(month_fees) AS month_fees
    FROM {{ ref('int_revenue_fees_monthly_per_user') }}
    {% if start_month and end_month %}
    WHERE month >= toDate('{{ start_month }}')
      AND month <= toDate('{{ end_month }}')
    {% else %}
    {{ apply_monthly_incremental_filter('month', 'month', false, lookback_days=2, lookback_res='month') }}
    {% endif %}
    GROUP BY month, user
)

SELECT
    month,
    countIf(month_fees >= {{ active_threshold_usd }}) AS users_cnt,
    round(sumIf(month_fees, month_fees >= {{ active_threshold_usd }}), 2) AS fees_total
FROM per_user
GROUP BY month

{% set active_threshold_usd = 6.0 %}
{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

{#
  Heavy aggregation (GROUP BY week, user over the 10M+-row per-user weekly
  table) OOMs as a view/table. Cron runs recompute only complete month
  partitions via insert_overwrite (upstream restates the trailing 4 weeks;
  the 35-day lookback covers it; partition grain == overwrite grain). The
  strategy resolves to `append` when start_month is set: refresh.py stages
  write non-overlapping month windows, and insert_overwrite would make each
  stage's REPLACE PARTITION wipe the previous ones
  (docs/lessons/staged-insert-overwrite-wipe.md).
#}
{{
  config(
    materialized='incremental',
    incremental_strategy=('append' if start_month else 'insert_overwrite'),
    engine='ReplacingMergeTree()',
    order_by='(week)',
    partition_by='toStartOfMonth(week)',
    pre_hook=[
        "SET max_bytes_before_external_group_by = 2000000000",
        "SET max_bytes_before_external_sort = 2000000000"
    ],
    post_hook=[
        "SET max_bytes_before_external_group_by = 0",
        "SET max_bytes_before_external_sort = 0"
    ],
    tags=['production','revenue','revenue_cross']
  )
}}

WITH per_user AS (
    SELECT
        week,
        user,
        sum(annual_rolling_fees) AS annual_rolling_fees
    FROM {{ ref('int_revenue_fees_weekly_per_user') }}
    {% if start_month and end_month %}
    WHERE toStartOfMonth(week) >= toDate('{{ start_month }}')
      AND toStartOfMonth(week) <= toDate('{{ end_month }}')
    {% else %}
    {{ apply_monthly_incremental_filter('week', 'week', false, lookback_days=35) }}
    {% endif %}
    GROUP BY week, user
)

SELECT
    week,
    countIf(annual_rolling_fees >= {{ active_threshold_usd }}) AS users_cnt,
    round(sumIf(annual_rolling_fees, annual_rolling_fees >= {{ active_threshold_usd }}), 2) AS annual_rolling_fees_total
FROM per_user
GROUP BY week

model.gnosis_dbt.int_revenue_fees_unifie.raw_code:
{{
  config(
    materialized='view',
    tags=['production','revenue','revenue_cross']
  )
}}

-- user is canonicalized through the June 2026 Safe migration so the same
-- person carries ONE address across all streams (gpay daily is already
-- canonical at the source; the remap is idempotent for it and covers the
-- holdings/sdai/gnosis_app streams here). CH LEFT JOIN fills '' on
-- misses, hence the empty-string guard.
WITH daily AS (
    SELECT 'holdings' AS stream_type, date, user, symbol, fees
    FROM {{ ref('int_revenue_holdings_fees_daily') }}

    UNION ALL

    SELECT 'sdai'     AS stream_type, date, user, symbol, fees
    FROM {{ ref('int_revenue_sdai_fees_daily') }}

    UNION ALL

    SELECT 'gpay'        AS stream_type, date, user, symbol, fees
    FROM {{ ref('int_revenue_gpay_fees_daily') }}

    UNION ALL

    SELECT 'gnosis_app'  AS stream_type, date, user, symbol, fees
    FROM {{ ref('int_revenue_gnosis_app_fees_daily') }}
)

SELECT
    d.stream_type AS stream_type,
    d.date        AS date,
    if(c.canonical_address != '', c.canonical_address, d.user) AS user,
    d.symbol      AS symbol,
    d.fees        AS fees
FROM daily d
LEFT JOIN {{ ref('int_execution_gpay_safe_canonical') }} c
    ON c.address = d.user

model.gnosis_dbt.int_revenue_fees_weekly.raw_code:
{#
  Windowed backfills (start_month) normally APPEND -- the full_refresh
  orchestrator / batch runner writes non-overlapping months, so append never
  duplicates. Pass reprocess_overwrite=true to re-run an OVERLAPPING window
  safely: delete+insert replaces the touched keys (no duplicate rows), mirroring
  int_execution_tokens_balances_native_daily / _pools_uniswap_v3_daily.

  IMPORTANT: this model unions many streams; a whole-window delete+insert across
  ALL of them OOMs the delete set. Reprocess ONE `slice` at a time (batch to
  bound memory), e.g.:
    dbt run -s int_revenue_fees_weekly_per_user \
      --vars 'start_month: 2026-03-01, end_month: 2026-07-01, reprocess_overwrite: true, slice: "holdings:EURe"'
#}
{% set lookback_weeks        = 4  %}
{% set window_history_weeks  = 52 %}

{% set all_streams = [
    ('holdings',    'int_revenue_holdings_fees_daily',    'EURe'),
    ('holdings',    'int_revenue_holdings_fees_daily',    'USDC.e'),
    ('holdings',    'int_revenue_holdings_fees_daily',    'BRLA'),
    ('holdings',    'int_revenue_holdings_fees_daily',    'ZCHF'),
    ('sdai',        'int_revenue_sdai_fees_daily',        'sDAI'),
    ('gpay',        'int_revenue_gpay_fees_daily',        'EURe'),
    ('gpay',        'int_revenue_gpay_fees_daily',        'GBPe'),
    ('gpay',        'int_revenue_gpay_fees_daily',        'USDC.e'),
    ('gnosis_app',  'int_revenue_gnosis_app_fees_daily',  'CRC'),
] %}

{# Optional `slice` var (comma-separated) selects which stream_type+symbol
   slices to process in this run. Stages in schema.yml use it so each run
   processes one slice at a time, keeping memory bounded. Format is
   `stream:SYMBOL` pairs; a bare `SYMBOL` matches every stream with that
   symbol. #}
{% set slice_filter = var('slice', none) %}
{% set streams = [] %}
{% if slice_filter %}
  {% set wanted = slice_filter.split(',') | map('trim') | list %}
  {% for s in all_streams %}
    {% set key_full = s[0] ~ ':' ~ s[2] %}
    {% if key_full in wanted or s[2] in wanted %}
      {% do streams.append(s) %}
    {% endif %}
  {% endfor %}
{% else %}
  {% set streams = all_streams %}
{% endif %}

{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

{{
  config(
    materialized='incremental',
    incremental_strategy=('delete+insert' if var('reprocess_overwrite', false) else ('append' if start_month else 'delete+insert')),
    engine='ReplacingMergeTree()',
    order_by='(week, stream_type, symbol, user)',
    partition_by='toStartOfMonth(week)',
    unique_key='(week, stream_type, symbol, user)',
    settings={'allow_nullable_key': 1},
    tags=['production','revenue','revenue_cross']
  )
}}

{% if is_incremental() and not (start_month and end_month) %}
WITH cutoff AS (
    SELECT coalesce(max(week), toDate('1970-01-01')) - INTERVAL {{ lookback_weeks }} WEEK AS cutoff_week
    FROM {{ this }}
)
{% endif %}

{% for stream_type, source_ref, symbol in streams %}
{% if not loop.first %}
UNION ALL
{% endif %}

SELECT
    week,
    '{{ stream_type }}' AS stream_type,
    symbol,
    user,
    week_fees,
    annual_rolling_fees
FROM (
    WITH weekly_sparse AS (
        SELECT
            toStartOfWeek(date, 1) AS week,
            user,
            symbol,
            round(sum(fees), 8) AS week_fees
        FROM {{ ref(source_ref) }}
        WHERE date < toStartOfWeek(today(), 1)
          AND symbol = '{{ symbol }}'
          {% if is_incremental() and not (start_month and end_month) %}
            AND toStartOfWeek(date, 1) >= (SELECT cutoff_week FROM cutoff) - INTERVAL {{ window_history_weeks }} WEEK
          {% elif start_month and end_month %}
            AND toStartOfWeek(date, 1) >= toDate('{{ start_month }}') - INTERVAL {{ window_history_weeks }} WEEK
            AND date <= addDays(toLastDayOfMonth(toDate('{{ end_month }}')), 6)
          {% endif %}
        GROUP BY week, user, symbol
    ),
    user_span AS (
        SELECT
            user,
            symbol,
            {% if is_incremental() and not (start_month and end_month) %}
              greatest(min(week),
                       (SELECT cutoff_week FROM cutoff) - INTERVAL {{ window_history_weeks }} WEEK) AS first_week,
              toStartOfWeek(today(), 1) - INTERVAL 1 WEEK AS last_week
            {% elif start_month and end_month %}
              greatest(min(week),
                       toDate('{{ start_month }}') - INTERVAL {{ window_history_weeks }} WEEK) AS first_week,
              least(
                toStartOfWeek(today(), 1) - INTERVAL 1 WEEK,
                toStartOfWeek(toLastDayOfMonth(toDate('{{ end_month }}')), 1)
              ) AS last_week
            {% else %}
              min(week) AS first_week,
              toStartOfWeek(today(), 1) - INTERVAL 1 WEEK AS last_week
            {% endif %}
        FROM weekly_sparse
        GROUP BY 1, 2
    ),
    calendar AS (
        SELECT
            user,
            symbol,
            arrayJoin(
                arrayMap(
                    i -> toDate(addWeeks(first_week, i)),
                    range(toUInt32(dateDiff('week', first_week, last_week) + 1))
                )
            ) AS week
        FROM user_span
    ),
    weekly_dense AS (
        SELECT
            c.week,
            c.user,
            c.symbol,
            coalesce(ws.week_fees, 0) AS week_fees
        FROM calendar c
        LEFT JOIN weekly_sparse ws
            ON  ws.week   = c.week
            AND ws.user   = c.user
            AND ws.symbol = c.symbol
    )
    SELECT
        week,
        user,
        symbol,
        week_fees,
        round(
            sum(week_fees) OVER (
                PARTITION BY user
                ORDER BY week
                ROWS BETWEEN 51 PRECEDING AND CURRENT ROW
            ),
            8
        ) AS annual_rolling_fees
    FROM weekly_dense
) s
WHERE (s.annual_rolling_fees > 0 OR s.week_fees > 0)
  {% if is_incremental() and not (start_month and end_month) %}
    AND s.week > (SELECT cutoff_week FROM cutoff)
  {% elif start_month and end_month %}
    AND toStartOfMonth(s.week) >= toDate('{{ start_month }}')
    AND toStartOfMonth(s.week) <= toDate('{{ end_month }}')
  {% endif %}
{% endfor %}

