{% endmacro %}

macro.gnosis_dbt.weekly_spine.macro_sql:
{% macro weekly_spine(start_date_expr, end_date_expr) %}
SELECT
  toStartOfWeek(toDate({{ start_date_expr }}), 1)
    + toIntervalWeek(n) AS week
FROM (
  SELECT arrayJoin(
    range(0, toUInt32(dateDiff(
      'week',
      toStartOfWeek(toDate({{ start_date_expr }}), 1),
      toStartOfWeek(toDate({{ end_date_expr }}),   1)
    )) + 1)
  ) AS n
)
{% endmacro %}

macro.gnosis_dbt.decode_hex_split.macro_sql:
{% macro decode_hex_split(column) %}
    arrayFilter(
      x -> x != '',
      splitByChar(
        ' ',
        arrayStringConcat(
          arrayMap(
            i -> if(
              reinterpretAsUInt8(substring(unhex({{ column }}), i, 1)) BETWEEN 32 AND 126,
              reinterpretAsString(substring(unhex({{ column }}), i, 1)),
              ' '
            ),
            range(1, length(unhex({{ column }})) + 1)
          ),
          ''
        )
      )
    )
{% endmacro %}

macro.gnosis_dbt.decode_hex_tokens.macro_sql:
{% macro decode_hex_tokens(column) %}
arrayFilter(
    x -> x != '',
    /* split on every “non word-ish” character (dash, @, space, etc.) */
    splitByRegexp(
        '[^A-Za-z0-9\\.]+',            -- ⇽ anything that isn’t a–z, 0–9 or “.”
        arrayStringConcat(
            arrayMap(
                i -> if(
                    reinterpretAsUInt8(substring(unhex(coalesce({{ column }}, '')), i, 1)) BETWEEN 32 AND 126,
                    reinterpretAsString(substring(unhex(coalesce({{ column }}, '')), i, 1)),
                    ' '
                ),
                range(1, length(unhex(coalesce({{ column }}, ''))) + 1)
            ),
            ''
        )
    )
)
{% endmacro %}

macro.gnosis_dbt.decode_hex_tokens2.macro_sql:
{% macro decode_hex_tokens2(column) %}
/* Safely decode a hex string column to printable tokens, returning [] on NULL/invalid */
arrayFilter(
  x -> x != '',
  splitByRegexp(
    '[^A-Za-z0-9\\.]+',
    arrayStringConcat(
      arrayMap(
        i -> if(
          reinterpretAsUInt8(substring(
            unhex(
              if(
                isNull({{ column }}) OR {{ column }} = '' 
                OR NOT match({{ column }}, '^[0-9A-Fa-f]+$')
                OR (length({{ column }}) % 2 = 1),
                '',
                {{ column }}
              )
            ),
            i, 1
          )) BETWEEN 32 AND 126,
          reinterpretAsString(substring(
            unhex(
              if(
                isNull({{ column }}) OR {{ column }} = '' 
                OR NOT match({{ column }}, '^[0-9A-Fa-f]+$')
                OR (length({{ column }}) % 2 = 1),
                '',
                {{ column }}
              )
            ),
            i, 1
          )),
          ' '
        ),
        range(
          1,
          length(unhex(
            if(
              isNull({{ column }}) OR {{ column }} = '' 
              OR NOT match({{ column }}, '^[0-9A-Fa-f]+$')
              OR (length({{ column }}) % 2 = 1),
              '',
              {{ column }}
            )
          )) + 1
        )
      ),
      ''
    )
  )
)
{% endmacro %}

macro.gnosis_dbt.cohort_bucket_yearly.macro_sql:
{% macro cohort_bucket_yearly(amount_col, include_below_one=true) %}
    multiIf(
