        '>=100'
    )
{% endmacro %}

macro.gnosis_dbt.resolve_factory_childre.macro_sql:
{% macro resolve_factory_children(protocol=none) %}

{% set factory_query %}
  SELECT
    factory_address,
    factory_events_model,
    creation_event_name,
    child_address_param,
    child_contract_type,
    child_abi_source_address,
    protocol,
    start_blocktime
  FROM {{ ref('contracts_factory_registry') }}
  {% if protocol %}
    WHERE protocol = '{{ protocol }}'
  {% endif %}
{% endset %}

{% set factories = run_query(factory_query) %}

{% if factories | length == 0 %}
  {# Return empty result set matching the expected schema #}
  SELECT
    '' AS address,
    '' AS contract_type,
    '' AS abi_source_address,
    toUInt8(1) AS is_dynamic,
    '' AS start_blocktime,
    '' AS discovery_source
  WHERE 1 = 0
{% else %}
  {% for row in factories %}
    {% if not loop.first %}
    UNION ALL
    {% endif %}
    SELECT
      lower(decoded_params['{{ row.child_address_param }}']) AS address,
      '{{ row.child_contract_type }}' AS contract_type,
      lower('{{ row.child_abi_source_address }}') AS abi_source_address,
      toUInt8(1) AS is_dynamic,
      '{{ row.start_blocktime }}' AS start_blocktime,
      '{{ row.creation_event_name }}' AS discovery_source
    FROM {{ ref(row.factory_events_model) }}
    WHERE event_name = '{{ row.creation_event_name }}'
    GROUP BY 1
  {% endfor %}
{% endif %}

{% endmacro %}

macro.gnosis_dbt.build_journey_lookback.macro_sql:
{% macro build_journey_lookback(lookback_days, sector) %}
{% set conversion_model = 'int_execution_' ~ sector ~ '_conversions' %}
{% set events_model = 'int_execution_' ~ sector ~ '_user_events_unified' %}

{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month',   none) %}

{{ config(
    materialized='incremental',
    incremental_strategy='insert_overwrite',
    engine='ReplacingMergeTree()',
    order_by=(
      '(conversion_date, conversion_kind, identity_role, user_pseudonym, conversion_ts, event_kind)'
      if sector == 'gpay'
      else '(conversion_date, conversion_kind, user_pseudonym, conversion_ts, event_kind)'
    ),
    partition_by='toStartOfMonth(conversion_date)',
    settings={'allow_nullable_key': 1},
    tags=['production', 'mta', 'execution', sector, 'mart'],
    pre_hook=[
        "SET join_algorithm = 'grace_hash'",
        "SET grace_hash_join_initial_buckets = 64"
    ],
    post_hook=[
        "SET join_algorithm = 'default'"
    ]
) }}

WITH conversions AS (
    SELECT *
    FROM {{ ref(conversion_model) }}
    WHERE 1=1
    {%- if sector == 'gpay' %}
      -- Exclude the delegate identity_role: it represents the shared
      -- gpay delegate wallet (system infrastructure), not a per-user
      -- journey participant. Every gpay user routes through it, so its
      -- 30d event pool averages ~14k touches per (conversion × event_kind)
      -- and dominates the join cost (~99.8% of intermediate rows in
      -- our May-2025 sample). Owner + safe_self preserve the real
      -- end-user journeys.
      AND identity_role != 'delegate'
    {%- endif %}
    {%- if start_month and end_month %}
      AND toStartOfMonth(conversion_date) >= toDate('{{ start_month }}')
      AND toStartOfMonth(conversion_date) <= toDate('{{ end_month }}')
    {%- else %}
      {{ apply_monthly_incremental_filter('conversion_date', 'conversion_date', add_and=True) }}
    {%- endif %}
),
active_users AS (
    SELECT DISTINCT
        user_pseudonym
        {%- if sector == 'gpay' %},
        identity_role
        {%- endif %}
    FROM conversions
),
events_window AS (
    SELECT e.*
    FROM {{ ref(events_model) }} e
    INNER JOIN active_users u
        ON e.user_pseudonym = u.user_pseudonym
        {%- if sector == 'gpay' %}
        AND e.identity_role = u.identity_role
        {%- endif %}
    WHERE 1=1
    {%- if start_month and end_month %}
      AND e.event_date >= addDays(toDate('{{ start_month }}'), -{{ lookback_days }})
      AND e.event_date <= toLastDayOfMonth(toDate('{{ end_month }}'))
    {%- else %}
      {{ apply_monthly_incremental_filter(
            'e.event_date',
            'conversion_date',
            add_and=True,
            lookback_days=lookback_days) }}
    {%- endif %}
),
joined AS (
    SELECT
        c.user_pseudonym                                              AS user_pseudonym,
        {%- if sector == 'gpay' %}
        c.identity_role                                               AS identity_role,
        {%- endif %}
        c.conversion_kind                                             AS conversion_kind,
        c.conversion_ts                                               AS conversion_ts,
        c.conversion_date                                             AS conversion_date,
        c.conversion_amount_usd                                       AS conversion_amount_usd,
        c.conversion_token                                            AS conversion_token,
        e.event_source                                                AS event_source,
        e.event_kind                                                  AS event_kind,
        e.event_ts                                                    AS touch_ts,
        dateDiff('day', toDate(e.event_ts), c.conversion_date)        AS lag_days
    FROM conversions c
    INNER JOIN events_window e
        ON  e.user_pseudonym = c.user_pseudonym
        {%- if sector == 'gpay' %}
        AND e.identity_role  = c.identity_role
        {%- endif %}
        AND e.event_ts       <  c.conversion_ts
        AND e.event_ts       >= c.conversion_ts - INTERVAL {{ lookback_days }} DAY
        AND e.event_kind     != {{ conversion_kind_to_event_kind('c.conversion_kind') }}
)
SELECT
    user_pseudonym,
    {%- if sector == 'gpay' %}
    identity_role,
    {%- endif %}
    conversion_kind,
    conversion_ts,
    conversion_date,
    any(conversion_amount_usd)                          AS conversion_amount_usd,
    any(conversion_token)                               AS conversion_token,
    any(event_source)                                   AS event_source,
    event_kind,
    count()                                             AS n_touches,
    min(touch_ts)                                       AS first_touch_ts,
    max(touch_ts)                                       AS last_touch_ts,
    sum(exp(-1.0 * lag_days / 7.0))                     AS td_sum
FROM joined
GROUP BY
    user_pseudonym,
    {%- if sector == 'gpay' %}
    identity_role,
    {%- endif %}
    conversion_kind,
    conversion_ts,
    conversion_date,
    event_kind
{% endmacro %}

macro.gnosis_dbt.list_partitions.macro_sql:
{% macro list_partitions(database, table_name) %}
  {# Read-only: log active partitions (value, id, row count, part count) for a table.
     Use to verify the partition-key format before drop_partition, and to confirm a
     drop/rebuild landed. #}
  {% set sql %}
    SELECT partition, partition_id, sum(rows) AS rows, count() AS parts
    FROM system.parts
    WHERE active = 1
      AND database = '{{ database }}'
      AND table = '{{ table_name }}'
    GROUP BY partition, partition_id
    ORDER BY partition
  {% endset %}
  {% if execute %}
    {% set rows = run_query(sql).rows %}
    {% do log("partitions for " ~ database ~ "." ~ table_name ~ " (" ~ (rows | length) ~ " active):", info=True) %}
    {% for r in rows %}
      {% do log("  partition=" ~ r[0] ~ " id=" ~ r[1] ~ " rows=" ~ r[2] ~ " parts=" ~ r[3], info=True) %}
    {% endfor %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.drop_partition.macro_sql:
{% macro drop_partition(database, table_name, partition) %}
  {# Run `ALTER TABLE <db>.<table> DROP PARTITION '<p>'`. Physically removes a whole
     partition's parts (unlike delete+insert, which is unique_key-scoped and leaves
     sparse-dropped / stale rows behind). Use before a bounded rebuild when the corrected
     grain-state for some keys is "no row" (e.g. cumulative balance models where a holder
     fully exited within the window). alter_sync=2 waits for the change to apply. #}
  {% set sql %}
    ALTER TABLE {{ database }}.{{ table_name }}
    DROP PARTITION '{{ partition }}'
    SETTINGS alter_sync = 2
  {% endset %}
  {% do log("ALTER TABLE " ~ database ~ "." ~ table_name ~ " DROP PARTITION '" ~ partition ~ "' …", info=True) %}
  {% do run_query(sql) %}
  {% do log("DROP PARTITION '" ~ partition ~ "' on " ~ database ~ "." ~ table_name ~ " completed", info=True) %}
{% endmacro %}

macro.gnosis_dbt.drop_view.macro_sql:
{% macro drop_view(database, view_name) %}
  {# Drop a stale VIEW left behind after a model rename/retire (dbt does not
     drop removed models). Guarded: refuses anything that is not engine=View,
     so a mistyped name can never drop a physical table. #}
  {% set check_sql %}
    SELECT engine FROM system.tables
    WHERE database = '{{ database }}' AND name = '{{ view_name }}'
  {% endset %}
  {% if execute %}
    {% set rows = run_query(check_sql).rows %}
    {% if rows | length == 0 %}
      {% do log(database ~ "." ~ view_name ~ " does not exist — nothing to drop", info=True) %}
    {% elif rows[0][0] != 'View' %}
      {% do exceptions.raise_compiler_error(database ~ "." ~ view_name ~ " is engine=" ~ rows[0][0] ~ ", not a View — refusing to drop") %}
    {% else %}
      {% do run_query("DROP VIEW " ~ database ~ ".`" ~ view_name ~ "`") %}
      {% do log("Dropped view " ~ database ~ "." ~ view_name, info=True) %}
    {% endif %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.apply_monthly_increment.macro_sql:
{% macro apply_monthly_incremental_filter(source_field, destination_field=None, add_and=False, lookback_days=1, lookback_res='day', filters_sql='') %}
  {% if is_incremental() %}
    {% set dest_field = destination_field if destination_field is not none else source_field %}
    {# `price_lookback_days` widens the window for every caller of this macro.
       Used by scripts/maintenance/refill_after_price_gap.sh to recover after a
       prices-source gap: the lineage selector (`int_execution_token_prices_daily+`)
       picks up every consumer transitively, and the var here makes them all
       re-pull the wider window without per-model edits or a tag registry. #}
    {% set effective_lookback = var('price_lookback_days', lookback_days) | int %}
    {% set lb_days = effective_lookback - 1 %}
    {% set incr_end = mb_var('incremental_end_date') %}
    {% set strategy = config.get('incremental_strategy') %}

    {{ "AND " if add_and else "WHERE " }}
    {% if strategy == 'insert_overwrite' %}
      {# Whole-partition recompute: return COMPLETE months so REPLACE PARTITION is
         lossless, EVEN when the microbatch runner set incremental_end_date. A
         day-level lower bound here would make REPLACE PARTITION wipe the rest of
         the month (the June data-loss bug). When incr_end is set we still honor it
         as an upper cap so the runner stays the ceiling authority. #}
      toStartOfMonth(toDate({{ source_field }})) >= (
        SELECT toStartOfMonth(addDays(max(toDate(x1.{{ dest_field }})), -{{ lb_days }}))
        FROM {{ this }} AS x1
        WHERE 1=1 {{ filters_sql }}
      )
      {% if incr_end is not none %}
      AND toDate({{ source_field }}) <= toDate('{{ incr_end }}')
      {% endif %}
    {% elif incr_end is not none %}
      {# No-overlap microbatch path: strict > max(target_date), <= incr_end.
         Lookback is intentionally suppressed — the microbatch runner is the
         authority on what's been processed. Allowing the macro's lookback
         here would re-pull old days under `append` strategy and create
         duplicates that we'd then need OPTIMIZE FINAL to clean up. #}
      toDate({{ source_field }}) > (
        SELECT coalesce(max(toDate(x1.{{ dest_field }})), toDate('1970-01-01'))
        FROM {{ this }} AS x1
        WHERE 1=1 {{ filters_sql }}
      )
      AND toDate({{ source_field }}) <= toDate('{{ incr_end }}')
    {% else %}
      {# Original lookback path — used when called outside the microbatch runner. #}
      toStartOfMonth(toDate({{ source_field }})) >= (
        SELECT toStartOfMonth(addDays(max(toDate(x1.{{ dest_field }})), -{{ lb_days }}))
        FROM {{ this }} AS x1
        WHERE 1=1 {{ filters_sql }}
      )
      AND toDate({{ source_field }}) >= (
        SELECT
          {% if lookback_res == 'week' %}
            toStartOfWeek(addDays(max(toDate(x2.{{ dest_field }})), -{{ lb_days }}))
          {% elif lookback_res == 'month' %}
            toStartOfMonth(addDays(max(toDate(x2.{{ dest_field }})), -{{ lb_days }}))
          {% else %}
            addDays(max(toDate(x2.{{ dest_field }})), -{{ lb_days }})
          {% endif %}

        FROM {{ this }} AS x2
        WHERE 1=1 {{ filters_sql }}
      )
    {% endif %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.dedup_source.macro_sql:
{% macro dedup_source(source_ref, partition_by, columns='*', pre_filter=none) %}
{#
  Deduplicates a source table using ROW_NUMBER with an optional pre-filter
  that runs BEFORE the window function, enabling ClickHouse partition pruning.

  Args:
    source_ref  : source() or ref() expression
    partition_by: comma-separated dedup key columns (e.g. 'block_number, log_index')
    columns     : columns to SELECT (default '*')
    pre_filter  : SQL WHERE clause body (without WHERE keyword), applied before ROW_NUMBER
#}
SELECT {{ columns }}
FROM (
    SELECT
        {{ columns }},
        ROW_NUMBER() OVER (
            PARTITION BY {{ partition_by }}
            ORDER BY insert_version DESC
        ) AS _dedup_rn
    FROM {{ source_ref }}
    {% if pre_filter is not none and pre_filter | trim != '' %}
    WHERE {{ pre_filter }}
    {% endif %}
)
WHERE _dedup_rn = 1
{% endmacro %}

macro.gnosis_dbt.envio_latest.macro_sql:
{% macro envio_latest(source_name, table_name, cols, key='id', version='_synced_block', pre_filter=none) %}
SELECT
