    {%- for c in cols %},
    argMax({{ c }}, {{ version }}) AS {{ c }}
    {%- endfor %}
FROM {{ source(source_name, table_name) }}
{%- if pre_filter is not none and pre_filter | trim != '' %}
WHERE {{ pre_filter }}
{%- endif %}
GROUP BY {{ key }}
HAVING max(_deleted) = 0
{% endmacro %}

