macro.gnosis_dbt.get_max_int.macro_sql:
{% macro get_max_int(model_name, column_name) %}
  {# Sentinel-emitting macro consumed by the microbatch runner's range-template
     auto-discovery. Returns the maximum integer value of `column_name` from
     the given model. Used to detect when new buckets need to be synthesized
     (e.g. a new validator_index range that hasn't been declared in
     meta.full_refresh.stages yet).

     Output format (parsed by dbt_incremental_runner.maybe_extend_stages):
       MAX_INT_RESULT::<model_name>::<column_name>::<integer or NULL>

     NOTE: deliberately NOT `FINAL` -- see get_max_date.sql. A single max() cannot be
     changed by deduplication, while `FINAL` forces a full merge-on-read that blows the
     memory ceiling on the large balance tables (measured 2026-09-19, code 241).
  #}
  {% if execute %}
    {% set rel = ref(model_name) %}
    {% set sql %}
      SELECT toString(max({{ column_name }}))
      FROM {{ rel }}
    {% endset %}
    {% set result = run_query(sql) %}
    {% set value = 'NULL' %}
    {% if result and result.rows and result.rows | length > 0 and result.rows[0][0] is not none %}
      {% set value = result.rows[0][0] %}
    {% endif %}
    {% do log("MAX_INT_RESULT::" ~ model_name ~ "::" ~ column_name ~ "::" ~ value, info=True) %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.get_distinct_values.macro_sql:
{% macro get_distinct_values(model_name, column_name, max_values=1000) %}
  {# Enumerate distinct values of `column_name` from the given model. Used by
     the runner to expand enum-keyed stages from a `range_template` block.

     Output (one sentinel line per value, deterministic order):
       DISTINCT_VALUE::<model_name>::<column_name>::<value>
     Followed by a sentinel marking end-of-stream:
       DISTINCT_VALUES_END::<model_name>::<column_name>::<count>

     `max_values` guards against accidentally enumerating high-cardinality
     columns (would produce thousands of stages). Default 1000 — runner will
     warn and refuse if the actual count exceeds this.
  #}
  {% if execute %}
    {% set rel = ref(model_name) %}
    {% set sql %}
      SELECT toString({{ column_name }}) AS v
      FROM {{ rel }} FINAL
      WHERE {{ column_name }} IS NOT NULL
      GROUP BY {{ column_name }}
      ORDER BY v
      LIMIT {{ max_values + 1 }}
    {% endset %}
    {% set result = run_query(sql) %}
    {% set rows = result.rows if (result and result.rows) else [] %}
    {% if rows | length > max_values %}
      {% do log("DISTINCT_VALUES_OVERFLOW::" ~ model_name ~ "::" ~ column_name ~ "::" ~ max_values, info=True) %}
    {% else %}
      {% for row in rows %}
        {% do log("DISTINCT_VALUE::" ~ model_name ~ "::" ~ column_name ~ "::" ~ row[0], info=True) %}
      {% endfor %}
      {% do log("DISTINCT_VALUES_END::" ~ model_name ~ "::" ~ column_name ~ "::" ~ rows | length, info=True) %}
    {% endif %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.get_first_seen_date.macro_sql:
{% macro get_first_seen_date(model_name, date_column, where_filter='') %}
  {# Find the earliest `date_column` value matching an optional WHERE filter.
     Used by the runner to bootstrap a newly-synthesized stage from the moment
     its key range first appeared in the upstream — avoids "today" or "1970"
     bootstrap policies that lose history or backfill too aggressively.

     Output:
       FIRST_SEEN_DATE_RESULT::<model_name>::<date_column>::<YYYY-MM-DD or NULL>

     NOTE: deliberately NOT `FINAL` -- see get_max_date.sql. A single min() over a key
     column cannot be changed by deduplication, while `FINAL` forces a full merge-on-read
     that blows the memory ceiling on the large balance tables (measured 2026-09-19).
  #}
  {% if execute %}
    {% set rel = ref(model_name) %}
    {% set sql %}
      SELECT toString(min(toDate({{ date_column }})))
      FROM {{ rel }}
      {% if where_filter %}
      WHERE {{ where_filter }}
      {% endif %}
    {% endset %}
    {% set result = run_query(sql) %}
    {% set value = 'NULL' %}
    {% if result and result.rows and result.rows | length > 0 and result.rows[0][0] is not none and result.rows[0][0] != '' %}
      {% set value = result.rows[0][0] %}
    {% endif %}
    {% do log("FIRST_SEEN_DATE_RESULT::" ~ model_name ~ "::" ~ date_column ~ "::" ~ value, info=True) %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.get_max_date.macro_sql:
{% macro get_max_date(model_name, date_column, where_filter='') %}
  {# Emit a sentinel log line that the microbatch runner parses out of stdout.
     Avoids the need for a separate ClickHouse client in the runner — we reuse
     the dbt profile via `dbt run-operation`. Format:
       MAX_DATE_RESULT::<model_name>::<date_column>::<YYYY-MM-DD>

     `where_filter` is an optional SQL fragment without the WHERE keyword,
     used so the runner can read max(date) PER STAGE for staged models — e.g.
     "validator_index >= 0 AND validator_index < 100000". Without it, a model
     whose stages cover disjoint key ranges with different historical maxes
     would only see the global max, leading the runner to schedule slices
     that the per-stage macro filter then expands into a huge backfill.

     NOTE: deliberately NOT `FINAL`. This macro only reads max() of one column, and
     deduplication cannot change a maximum -- duplicate copies of a key carry the same
     or a lower value. `FINAL` forces a full merge-on-read instead: measured 2026-09-19
     on int_rpc_state_indexer_token_balances_daily (425M rows) it died with ClickHouse
     code 241 (memory limit exceeded) while the same query without it returned in 42 s.
     The runner swallowed that failure and silently re-bootstrapped 7 slices every night
     on both large balance models, which also masked the real watermark.
  #}
  {% if execute %}
    {% set rel = ref(model_name) %}
    {% set sql %}
      SELECT toString(coalesce(max(toDate({{ date_column }})), toDate('1970-01-01')))
      FROM {{ rel }}
      {% if where_filter %}
      WHERE {{ where_filter }}
      {% endif %}
    {% endset %}
    {% set result = run_query(sql) %}
    {% set value = '1970-01-01' %}
    {% if result and result.rows and result.rows | length > 0 %}
      {% set value = result.rows[0][0] %}
    {% endif %}
    {% do log("MAX_DATE_RESULT::" ~ model_name ~ "::" ~ date_column ~ "::" ~ value, info=True) %}
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.clean_elementary_orphan.macro_sql:
{% macro clean_elementary_orphaned_tables() %}
    {# Drop orphaned Elementary tmp tables left behind by crashed runs.
       Elementary's on_run_end hook only cleans tables from the current run's
       cache — tables from interrupted runs persist and count toward the
       ClickHouse max_table_num_to_throw limit (default 1000). #}
    {% for db in ['elementary', 'dbt'] %}
        {% set orphan_query %}
            SELECT database, name
            FROM system.tables
            WHERE database = '{{ db }}'
              AND name LIKE '%__tmp_%'
        {% endset %}

        {% set orphans = run_query(orphan_query).rows %}
        {% if orphans | length > 0 %}
            {{ log("Found " ~ orphans | length ~ " orphaned tmp tables in " ~ db, info=True) }}
        {% endif %}

        {% for row in orphans %}
            {% set fqn = row[0] ~ '.`' ~ row[1] ~ '`' %}
            {{ log("Dropping orphaned tmp table: " ~ fqn, info=True) }}
            {% do run_query("DROP TABLE IF EXISTS " ~ fqn ~ " SYNC") %}
        {% endfor %}
    {% endfor %}
{% endmacro %}

macro.gnosis_dbt.kill_failed_mutations.macro_sql:
{% macro kill_failed_mutations() %}
    {# Kill ClickHouse mutations stuck in a failed state.
       Incremental models use DELETE + INSERT which creates mutations.
       If a previous run crashed, the mutation references a temp table
       (__dbt_new_data_*) that no longer exists, poisoning the table
       so all future writes fail with Code 341. #}
    {% set failed_query %}
        SELECT database, table, mutation_id,
               splitByChar('\n', latest_fail_reason)[1] as reason
        FROM system.mutations
        WHERE is_done = 0
          AND latest_fail_reason != ''
          AND database = 'dbt'
    {% endset %}

    {% set failed = run_query(failed_query).rows %}
    {% if failed | length > 0 %}
        {{ log("Found " ~ failed | length ~ " failed mutations to kill", info=True) }}
    {% endif %}

    {% for row in failed %}
        {% set db = row[0] %}
        {% set tbl = row[1] %}
        {% set mid = row[2] %}
        {{ log("Killing failed mutation " ~ mid ~ " on " ~ db ~ "." ~ tbl, info=True) }}
        {% do run_query("KILL MUTATION WHERE database = '" ~ db ~ "' AND table = '" ~ tbl ~ "' AND mutation_id = '" ~ mid ~ "'") %}
    {% endfor %}
{% endmacro %}

macro.gnosis_dbt.drop_dbt_trash.macro_sql:
{% macro drop_dbt_trash(database_name) %}
    {{ log("Dropping leftover dbt tables in " ~ database_name, info=True) }}

    -- 1) Gather the list of leftover tables
    {% set trash_tables_query %}
      SELECT name
      FROM system.tables
      WHERE database = '{{ database_name }}'
        AND name LIKE '%__dbt_%'
    {% endset %}

    {% set trash_tables = run_query(trash_tables_query).rows %}

    -- 2) Loop over each table name and DROP it
    {% for row in trash_tables %}
        {% set table_name = row[0] %}
        {{ log("Dropping table " ~ table_name, info=True) }}

        -- Here is where we actually run the DDL drop command
        {% do run_query("DROP TABLE IF EXISTS " ~ database_name ~ "." ~ table_name) %}
    {% endfor %}
{% endmacro %}

macro.gnosis_dbt.circles_chain_now_ts.macro_sql:
{% macro circles_chain_now_ts() -%}
(
    SELECT coalesce(max(timestamp), toUInt32(toUnixTimestamp(now())))
    FROM {{ source('execution', 'blocks') }}
)
{%- endmacro %}

macro.gnosis_dbt.circles_demurrage_facto.macro_sql:
{% macro circles_demurrage_factor(last_activity_ts, now_ts=none, inflation_day_zero=1602720000) -%}
{% if now_ts is none %}
  {% set now_ts = circles_chain_now_ts() %}
{% endif %}
toDecimal256(
  pow(
    toDecimal256('0.9998013320085989574306481700129226782902039065082930593676448873', 64),
    intDiv({{ now_ts }} - {{ inflation_day_zero }}, 86400)
    - intDiv({{ last_activity_ts }} - {{ inflation_day_zero }}, 86400)
  ),
  18
)
{%- endmacro %}

macro.gnosis_dbt.circles_strip_0x.macro_sql:
{% macro circles_strip_0x(value) -%}
if(
  startsWith(lower({{ value }}), '0x'),
  substring({{ value }}, 3),
  {{ value }}
)
{%- endmacro %}

macro.gnosis_dbt.circles_token_id_from_a.macro_sql:
{% macro circles_token_id_from_avatar(avatar) -%}
reinterpretAsUInt256(
  concat(
    reverse(
      unhex(
        lower({{ circles_strip_0x(avatar) }})
      )
    ),
    unhex(repeat('00', 12))
  )
)
{%- endmacro %}

macro.gnosis_dbt.circles_avatar_from_tok.macro_sql:
