macro.gnosis_dbt.create_circles_avatar_m.macro_sql:
{% macro create_circles_avatar_metadata_table() %}
  {% set sql %}
    CREATE TABLE IF NOT EXISTS circles_avatar_metadata_raw
    (
      avatar          LowCardinality(String),
      metadata_digest String,
