macro.gnosis_dbt.fetch_abi_from_blocksco.macro_sql:
{% macro fetch_abi_from_blockscout(contract_address) %}
    {% set blockscout_query %}
        WITH src AS (
            SELECT body 
            FROM url(
                'https://gnosis.blockscout.com/api/v2/smart-contracts/{{ contract_address | lower }}',
                'Raw',
                'body String'
            )
        )
        SELECT 
            JSONExtractRaw(body, 'abi') AS abi_json,
            JSONExtractString(body, 'name') AS contract_name,
            JSONExtractArrayRaw(body, 'implementations') AS implementations
        FROM src
        LIMIT 1
    {% endset %}

    {% set abi_result = run_query(blockscout_query) %}

    {% if abi_result.rows | length > 0 %}
        {% set result = {
            'abi_json': abi_result[0][0],
            'contract_name': abi_result[0][1],
            'implementations': abi_result[0][2]
        } %}

        {{ return(result) }}
    {% else %}
        {{ log("Failed to fetch ABI for contract " ~ contract_address, info=true) }}
        {{ return({'abi_json': '[]', 'contract_name': '', 'implementations': '[]'}) }}
    {% endif %}
{% endmacro %}

macro.gnosis_dbt.decode_array_component.macro_sql:
{% macro decode_array_component(args_raw_hex, head_words, param_objs, i, j, component_type) %}
  {% if component_type == 'string' %}
    arrayMap(k ->
      replaceRegexpAll(
        reinterpretAsString(unhex(
          substring(
            {{ args_raw_hex }},
            (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2)
              + toUInt64(reinterpretAsUInt256(reverse(unhex(
                  substring(
                    {{ args_raw_hex }},
                    (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
                      substring({{ args_raw_hex }},
                                (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                                64)))
                    ))) * 2),
                    64
                  )
                )))) * 2
              + 64
              + toUInt64(reinterpretAsUInt256(reverse(unhex(
                  substring(
                    {{ args_raw_hex }},
                    (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
                      substring({{ args_raw_hex }},
                                (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                                64)))
                    ))) * 2) + 64 + k*64,
                    64
                  )
                )))) * 2,
            toUInt64(reinterpretAsUInt256(reverse(unhex(
              substring(
                {{ args_raw_hex }},
                (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
                  substring({{ args_raw_hex }},
                            (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                            64)))
                ))) * 2)
                  + toUInt64(reinterpretAsUInt256(reverse(unhex(
                      substring(
                        {{ args_raw_hex }},
                        (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
                          substring({{ args_raw_hex }},
                                    (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                                    64)))
                        ))) * 2) + 64 + k*64,
                        64
                      )
                    )))) * 2,
                64
              )
            )))) * 2
          )
        )),
        '\0',''
      ),
      range(
        toUInt64(reinterpretAsUInt256(reverse(unhex(
          substring(
            {{ args_raw_hex }},
            (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
              substring({{ args_raw_hex }},
                        (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                        64)))
            ))) * 2),
            64
          )
        ))))
      )
    )
  {% elif component_type == 'address' %}
    arrayMap(k ->
      concat(
        '0x',
        substring(
          substring(
            {{ args_raw_hex }},
            (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
              substring({{ args_raw_hex }},
                        (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                        64)))
            ))) * 2) + 64 + k*64,
            64
          ),
          25, 40
        )
      ),
      range(
        toUInt64(reinterpretAsUInt256(reverse(unhex(
          substring(
            {{ args_raw_hex }},
            (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(
              substring({{ args_raw_hex }},
                        (1 + toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement({{ head_words }},{{ i }}+1))))) * 2) + {{ j }}*64,
                        64)))
            ))) * 2),
            64
          )
        ))))
      )
    )
  {% else %}
    []
  {% endif %}
{% endmacro %}

macro.gnosis_dbt.decode_calls.macro_sql:
{% macro decode_calls(
        tx_table,
        contract_address=null,
        contract_address_ref=null,
        contract_type_filter=null,
        abi_source_address=null,
        output_json_type=false,
        incremental_column='block_timestamp',
        selector_column='to_address',
        start_blocktime=null,
        chain='gnosis'
) %}

{% if contract_address_ref %}
  {% if contract_type_filter %}
    {% set type_where = " WHERE cw.contract_type = '" ~ contract_type_filter ~ "'" %}
    {% set type_and = " AND cw.contract_type = '" ~ contract_type_filter ~ "'" %}
  {% else %}
    {% set type_where = "" %}
    {% set type_and = "" %}
  {% endif %}

  {# ----------------------------------------------------------------
     Detect whether the referenced whitelist/registry seed exposes an
     `abi_source_address` column. See decode_logs.sql for the full
     rationale — short version: proxy registries (e.g.
     `contracts_circles_registry`) have this column for ABI override,
     simple flat whitelists (e.g. `contracts_whitelist`) do not.
     When the column is missing, fall back to using `cw.address`
     directly so the JOIN and subquery references stay valid.
     ---------------------------------------------------------------- #}
  {% set has_abi_source_col = false %}
  {% if execute %}
    {% set _cw_columns = adapter.get_columns_in_relation(contract_address_ref) %}
    {% set _cw_column_names = _cw_columns | map(attribute='name') | map('lower') | list %}
    {% if 'abi_source_address' in _cw_column_names %}
      {% set has_abi_source_col = true %}
    {% endif %}
  {% endif %}

  {% set addr_filter = "lower(replaceAll(" ~ selector_column ~ ",'0x','')) IN (SELECT lower(replaceAll(cw.address,'0x','')) FROM " ~ contract_address_ref ~ " cw" ~ type_where ~ ")" %}
  {% if abi_source_address %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') = '" ~ (abi_source_address | lower | replace('0x', '') | trim) ~ "'" %}
  {% elif has_abi_source_col %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') IN (SELECT lower(replaceAll(coalesce(nullIf(cw.abi_source_address, ''), cw.address), '0x', '')) FROM " ~ contract_address_ref ~ " cw" ~ type_where ~ ")" %}
  {% else %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') IN (SELECT lower(replaceAll(cw.address, '0x', '')) FROM " ~ contract_address_ref ~ " cw" ~ type_where ~ ")" %}
  {% endif %}
{% else %}
  {% if contract_address is string %}
    {% set addr_list = [contract_address] %}
  {% else %}
    {% set addr_list = contract_address %}
  {% endif %}

  {% set normalized = [] %}
  {% for addr in addr_list %}
    {% set normalized_addr = addr | lower | replace('0x', '') | trim %}
    {% set _ = normalized.append(normalized_addr) %}
  {% endfor %}

  {% if normalized | length > 1 %}
    {% set addr_quoted = [] %}
    {% for addr in normalized %}
      {% set _ = addr_quoted.append("'" ~ addr ~ "'") %}
    {% endfor %}
    {% set addr_filter = "lower(replaceAll(" ~ selector_column ~ ", '0x', '')) IN (" ~ addr_quoted | join(', ') ~ ")" %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') IN (" ~ addr_quoted | join(', ') ~ ")" %}
  {% else %}
    {% set addr = normalized[0] %}
    {% set addr_filter = "replaceAll(lower(" ~ selector_column ~ "),'0x','') = '" ~ addr ~ "'" %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') = '" ~ addr ~ "'" %}
  {% endif %}
{% endif %}

{% set sig_sql %}
SELECT
    replaceAll(lower(contract_address), '0x', '') AS abi_contract_address,
    substring(signature,1,8) AS selector,
    function_name,
    arraySort(x -> toInt32OrZero(JSONExtractRaw(x,'position')),
              ifNull(JSONExtractArrayRaw(input_params), emptyArrayString())) AS params_raw,
    arrayMap(x -> JSONExtractString(x,'name'), params_raw) AS names,
    arrayMap(x -> JSONExtractString(x,'type'), params_raw) AS types
FROM {{ ref('function_signatures') }}
WHERE chain = '{{ chain }}'
  AND {{ abi_filter }}
{% endset %}

{% set sql_body %}
{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month', none) %}
{% set incr_end    = mb_var('incremental_end_date') %}

{# ---------------------------------------------------------------
   Auto-detect whether `tx_table` points at `execution.traces`. When
   it does, we normalise the trace column names (action_input / action_to
   / etc.) onto the `execution.transactions` shape so the rest of the
   macro stays unchanged. Also emit a `trace_address` column in that
   case — both for the dedup key (one tx can have many internal calls
   to the same target) and for the final output.

   For traces mode we also pre-filter to successful real calls
   (action_call_type IN (...) AND error IS NULL) so the downstream
   abi-join logic sees a clean stream.

   Safety: existing transactions-mode callers get byte-identical
   output — no new column, no new filter, no schema drift on their
   incremental tables.
   --------------------------------------------------------------- #}
{% set tx_table_name = (tx_table | string) | lower %}
{% set is_traces = '"traces"' in tx_table_name or tx_table_name.endswith('.traces') or tx_table_name.endswith('traces`') %}

WITH
  src AS (
    {% if is_traces %}
    SELECT
      block_number,
      block_timestamp,
      transaction_hash,
      transaction_index,
      insert_version,
      action_input                         AS input,
      action_to                            AS to_address,
      action_from                          AS from_address,
      action_value                         AS value_string,
      CAST(NULL AS Nullable(UInt64))       AS nonce,
      CAST(NULL AS Nullable(UInt64))       AS gas_price,
      trace_address                        AS trace_address
    FROM {{ tx_table }}
    WHERE action_call_type IN ('call','delegate_call','static_call')
      AND error IS NULL
    {% else %}
    -- `insert_version` is MATERIALIZED on execution.transactions so it's NOT
    -- picked up by `SELECT *`. Reference it explicitly so the dedup
    -- ROW_NUMBER further down can see it. The previous implementation
    -- dodged this by reading `{{ tx_table }}` directly, which allows
    -- referencing MATERIALIZED columns alongside `*`. Same trick here.
    SELECT *, insert_version FROM {{ tx_table }}
    {% endif %}
  ),
  tx AS (
    SELECT * FROM (
      SELECT *,
        row_number() OVER (
          PARTITION BY block_number, transaction_index{% if is_traces %}, trace_address{% endif %}
          ORDER BY insert_version DESC
        ) AS _dedup_rn
      FROM src
      WHERE {{ addr_filter }}
        {% if start_blocktime %}
          AND {{ incremental_column }} >= toDateTime('{{ start_blocktime }}')
        {% endif %}

        {# Batch window filter: used by refresh.py for batched full refresh #}
        {% if start_month is not none and end_month is not none %}
          AND {{ incremental_column }} >= toDateTime('{{ start_month }}')
          AND {{ incremental_column }} <  toDateTime('{{ end_month }}') + INTERVAL 1 MONTH
        {% endif %}

        {# Daily no-overlap watermark. block_number is strictly monotonic and
           immutable, so `> max(block_number)` appends each block exactly once
           with no anti-join (memory-light) and no shared-timestamp boundary
           that block_timestamp would hit. Reorg/late corrections go through a
           targeted --full-refresh, never the daily path.

           Watermark fetched at render time and embedded as LITERALS: a
           scalar subquery on block_number cannot prune partitions, forcing
           every run to read across the full traces span. The extra literal
           timestamp bound enables pruning and is safe because the strict
           block_number bound already excludes the watermark and everything
           before it. Empty/missing target => no watermark (same as before).

           is_incremental() guard: watermark only applies when appending to an
           existing incremental target — table-materialized callers and first
           builds skip it (see decode_logs.sql for the full rationale). #}
        {% if incremental_column and not flags.FULL_REFRESH and is_incremental() %}
          {% set _wm_bn = none %}{% set _wm_ts = none %}
          {% if execute %}
            {% set _wm = run_query("SELECT max(block_number), toString(max(" ~ incremental_column ~ ")) FROM " ~ this) %}
            {% set _wm_bn = _wm.columns[0].values()[0] %}
            {% set _wm_ts = _wm.columns[1].values()[0] %}
          {% endif %}
          {% if _wm_bn is not none %}
          AND block_number > {{ _wm_bn }}
          AND {{ incremental_column }} >= toDateTime('{{ _wm_ts }}')
          {% endif %}
          {# Microbatch upper bound: runner advances incremental_end_date one day
             at a time so each slice reads only that day's new blocks (bounded
             memory for catch-up). No-op on the plain daily path. #}
          {% if incr_end is not none %}
            AND toDate({{ incremental_column }}) <= toDate('{{ incr_end }}')
          {% endif %}
        {% endif %}
        AND length(replaceAll(coalesce(input,''),'0x','')) >= 8
    )
    WHERE _dedup_rn = 1
  ),
  {% if contract_address_ref %}
  tx_with_abi AS (
    SELECT
      t.*,
      {% if abi_source_address %}
      '{{ abi_source_address | lower | replace('0x', '') | trim }}' AS abi_join_address
      {% elif has_abi_source_col %}
      lower(replaceAll(coalesce(nullIf(cw.abi_source_address, ''), cw.address), '0x', '')) AS abi_join_address
      {% else %}
      lower(replaceAll(cw.address, '0x', '')) AS abi_join_address
      {% endif %}
    FROM tx t
    ANY LEFT JOIN {{ contract_address_ref }} cw
      ON lower(replaceAll(t.{{ selector_column }}, '0x', '')) = lower(replaceAll(cw.address, '0x', ''))
      {{ type_and }}
  ),
  {% else %}
  tx_with_abi AS (
    SELECT
      t.*,
      lower(replaceAll(t.{{ selector_column }}, '0x', '')) AS abi_join_address
    FROM tx t
  ),
  {% endif %}
  abi AS ( {{ sig_sql }} ),

  {# Offset/length guard: ClickHouse does not short-circuit if/multiIf (the old
     analyzer's INSERT ... SELECT path evaluates every branch, and
     short_circuit_function_evaluation=disable reproduces it in a SELECT), so
     every dynamic decode arm reads offsets and lengths for EVERY param
     regardless of type. When the param is not that type, the words it reads
     are arbitrary calldata (a tuple's inner offsets, string bytes, ...) and a
     huge "length" word overflows substring's Int64 length argument -> Code 69
     "Overflow in length argument of substring-like function", killing the
     whole slice (contracts_Seer_MarketFactory_calls, createCategoricalMarket
     tuple param, 2026-09-02). Every word read as an offset or length is
     therefore clamped with least(..., length(args_raw_hex)) before it is
     multiplied: a real ABI offset/length is always below the calldata length,
     so valid decodes are byte-identical, and a garbage word can no longer
     overflow an offset or length argument.

     Array-length guard: the same evaluate-every-arm behaviour means a misread
     array length (e.g. approve(spender,0), where amount=0 is read as offset 0
     and the spender's low bytes become the "length") can exceed range()'s 500M
     cap -> Code 69 ARGUMENT_OUT_OF_BOUND. Each dynamic range() is therefore capped at
     intDiv(length(args_raw_hex),64) = the max 32-byte words the calldata can
     hold; a real array can never exceed that, so valid decodes are unchanged. #}
  process AS (
    SELECT
      t.block_number,
      t.block_timestamp,
      t.transaction_hash,
      t.{{ selector_column }} AS contract_address,
      t.nonce,
      t.gas_price,
      t.value_string AS value,
      {% if is_traces %}t.trace_address AS trace_address,{% endif %}
      a.function_name,
      substring(replaceAll(t.input,'0x',''),1,8) AS call_selector,
      substring(replaceAll(t.input,'0x',''),9)   AS args_raw_hex,
      a.names      AS param_names,
      a.types      AS param_types,
      a.params_raw AS param_objs,
      length(a.types) AS n_params,

      arrayMap(i -> if(i*64 < length(args_raw_hex), substring(args_raw_hex, 1 + i*64, 64), NULL),
               range(greatest(length(param_types),1)*16)) AS head_words,

      arrayMap(i -> replaceRegexpOne(param_types[i+1], '\\[\\]$', ''), range(length(param_types))) AS base_types,

      arrayMap(i ->
        if(i >= n_params, NULL,
          if(param_types[i+1] = 'tuple',
            toJSONString(
              mapFromArrays(
                arrayMap(c -> coalesce(JSONExtractString(c,'name'),''),
                         ifNull(JSONExtractArrayRaw(arrayElement(param_objs,i+1),'components'), emptyArrayString())),
                arrayMap(j ->
                  if(
                    endsWith(
                      arrayElement(
                        arrayMap(c -> coalesce(JSONExtractString(c,'type'),''),
                                 ifNull(JSONExtractArrayRaw(arrayElement(param_objs,i+1),'components'), emptyArrayString())),
                        j+1
                      ),
                      '[]'
                    ),
                    toJSONString([]),
                    if(
                      arrayElement(
                        arrayMap(c -> coalesce(JSONExtractString(c,'type'),''),
                                 ifNull(JSONExtractArrayRaw(arrayElement(param_objs,i+1),'components'), emptyArrayString())),
                        j+1
                      ) = 'address',
                      concat('0x',
                        substring(
                          substring(
                            args_raw_hex,
                            (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + j*64,
                            64
                          ),
                          25, 40
                        )
                      ),
                      concat('0x',
                        substring(
                          args_raw_hex,
                          (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + j*64,
                          64
                        )
                      )
                    )
                  ),
                  range(
                    length(ifNull(JSONExtractArrayRaw(arrayElement(param_objs,i+1),'components'), emptyArrayString()))
                  )
                )
              )
            ),
            if(endsWith(param_types[i+1],'[]'),
              toJSONString(
                if(
                  base_types[i+1] = 'string',
                    arrayMap(k ->
                      replaceRegexpAll(
                        reinterpretAsString(unhex(
                          substring(
                            args_raw_hex,
                            (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2)
                              + least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                                  substring(args_raw_hex,
                                            (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64 + k*64,
                                            64)
                              )))), toUInt64(length(args_raw_hex))) * 2
                              + 64,
                            least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                              substring(args_raw_hex,
                                        (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2)
                                          + least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                                              substring(args_raw_hex,
                                                        (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64 + k*64,
                                                        64)
                                          )))), toUInt64(length(args_raw_hex))) * 2,
                                        64)
                            )))), toUInt64(length(args_raw_hex))) * 2
                          )
                        )),
                        '\0',''
                      ),
                      range(
                        least(
                          least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                            substring(args_raw_hex,
                                      (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2),
                                      64)
                          )))), toUInt64(length(args_raw_hex))),
                          intDiv(length(args_raw_hex), 64)
                        )
                      )
                    ),
                  multiIf(
                    base_types[i+1] = 'address',
                    arrayMap(k ->
                      concat('0x',
                        substring(
                          substring(
                            args_raw_hex,
                            (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64 + k*64,
                            64
                          ),
                          25, 40
                        )
                      ),
                      range(
                        least(
                          least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                            substring(args_raw_hex,
                                      (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2),
                                      64)
                          )))), toUInt64(length(args_raw_hex))),
                          intDiv(length(args_raw_hex), 64)
                        )
                      )
                    ),
                    base_types[i+1] = 'bytes32',
                    arrayMap(k ->
                      concat('0x',
                        substring(
                          args_raw_hex,
                          (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64 + k*64,
                          64
                        )
                      ),
                      range(
                        least(
                          least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                            substring(args_raw_hex,
                                      (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2),
                                      64)
                          )))), toUInt64(length(args_raw_hex))),
                          intDiv(length(args_raw_hex), 64)
                        )
                      )
                    ),
                    /* bool[] shares the uint decode path: each element is a
                       0/1 uint256 word. Output '0'/'1' strings inside the
                       JSON array. */
                    startsWith(base_types[i+1], 'uint')
                    OR base_types[i+1] = 'bool',
                    arrayMap(k ->
                      toString(reinterpretAsUInt256(reverse(unhex(
                        substring(
                          args_raw_hex,
                          (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64 + k*64,
                          64
                        )
                      )))),
                      range(
                        least(
                          least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                            substring(args_raw_hex,
                                      (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2),
                                      64)
                          )))), toUInt64(length(args_raw_hex))),
                          intDiv(length(args_raw_hex), 64)
                        )
                      )
                    ),
                    startsWith(base_types[i+1], 'int'),
                    arrayMap(k ->
                      toString(reinterpretAsInt256(reverse(unhex(
                        substring(
                          args_raw_hex,
                          (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64 + k*64,
                          64
                        )
                      )))),
                      range(
                        least(
                          least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                            substring(args_raw_hex,
                                      (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2),
                                      64)
                          )))), toUInt64(length(args_raw_hex))),
                          intDiv(length(args_raw_hex), 64)
                        )
                      )
                    ),
                    []
                  )
                )
              ),
              if(
                (param_types[i+1] = 'bytes') OR (param_types[i+1] = 'string'),
                substring(
                  args_raw_hex,
                  (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2) + 64,
                  least(toUInt64(reinterpretAsUInt256(reverse(unhex(
                    substring(args_raw_hex,
                              (1 + least(toUInt64(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))), toUInt64(length(args_raw_hex))) * 2), 64)
                  )))), toUInt64(length(args_raw_hex))) * 2
                ),
                if(arrayElement(head_words,i+1) IS NULL, NULL,
                  multiIf(
                    param_types[i+1] = 'address',
                      concat('0x', substring(arrayElement(head_words,i+1), 25, 40)),
                    /* bool is stored as a 0/1 uint256 word. Output '0'/'1'
                       for consistency with decode_logs and with uint*. */
                    startsWith(param_types[i+1], 'uint')
                    OR param_types[i+1] = 'bool',
                      toString(reinterpretAsUInt256(reverse(unhex(arrayElement(head_words,i+1))))),
                    startsWith(param_types[i+1], 'int'),
                      toString(reinterpretAsInt256(reverse(unhex(arrayElement(head_words,i+1))))),
                    param_types[i+1] = 'bytes32',
                      concat('0x', arrayElement(head_words,i+1)),
                    concat('0x', arrayElement(head_words,i+1))
                  )
                )
              )
            )
          )
        ),
        range(n_params)
      ) AS raw_values_str,

      arrayMap(i ->
        if(
          i < n_params AND param_types[i+1] = 'string' AND raw_values_str[i+1] IS NOT NULL,
            replaceRegexpAll(reinterpretAsString(unhex(raw_values_str[i+1])),'\0',''),
          if(
            i < n_params AND param_types[i+1] = 'bytes' AND raw_values_str[i+1] IS NOT NULL,
            concat('0x', raw_values_str[i+1]),
            raw_values_str[i+1]
          )
        ),
        range(n_params)
      ) AS param_values_str,

      {% if output_json_type %}
        mapFromArrays(param_names, param_values_str) AS decoded_input
      {% else %}
        toJSONString(mapFromArrays(param_names, param_values_str)) AS decoded_input
      {% endif %}

    FROM tx_with_abi AS t
    ANY LEFT JOIN abi AS a
      ON substring(replaceAll(t.input,'0x',''),1,8) = a.selector
     AND t.abi_join_address = a.abi_contract_address
  )

SELECT
  block_number,
  block_timestamp,
  transaction_hash,
  contract_address,
  nonce,
  gas_price,
  value,
  {% if is_traces %}trace_address,{% endif %}
  function_name,
  decoded_input
FROM process
{% endset %}

{{ sql_body | trim }}
{% endmacro %}

macro.gnosis_dbt.fetch_and_insert_abi.macro_sql:
{% macro fetch_and_insert_abi(address) %}
    -- Fetch the initial contract details from blockscout
    {% set contract_data = fetch_abi_from_blockscout(address) %}
    {% set abi_json = contract_data['abi_json'] %}
    {% set contract_name = contract_data['contract_name'] %}
    {% set implementations_array = contract_data['implementations'] %}

    {{ log("Contract " ~ address ~ " has name: " ~ contract_name, info=true) }}
    {{ log("Contract " ~ address ~ " implementations array: " ~ implementations_array, info=true) }}

    -- First insert the contract ABI
    {% if abi_json and abi_json != '[]' and abi_json != '{}' %}
        -- Escape single quotes for ClickHouse VALUES syntax
        {% set abi_safe = abi_json | replace("'", "\\'") %}

        -- Check if this contract entry already exists
        {% set check_existing_sql %}
            SELECT count(*) as cnt
            FROM contracts_abi
            WHERE contract_address = '{{ address }}'
              AND implementation_address = ''
        {% endset %}

        {% set existing_result = run_query(check_existing_sql) %}
        {% set exists = existing_result.rows[0][0] > 0 %}

        {% if exists %}
            -- If exists, first delete the existing entry
            {% set delete_sql %}
                ALTER TABLE contracts_abi 
                DELETE WHERE contract_address = '{{ address }}' AND implementation_address = ''
            {% endset %}

            {{ log("Deleting existing ABI for " ~ address, info=true) }}
            {% do run_query(delete_sql) %}
        {% endif %}

        -- Insert the contract ABI
        {% set insert_sql %}
            INSERT INTO contracts_abi (
                contract_address, 
                implementation_address,
                abi_json, 
                contract_name,
                source, 
                updated_at,
                chain
            )
            VALUES (
                '{{ address }}', 
                '',
                '{{ abi_safe }}',
                '{{ contract_name | replace("'", "\\'") }}',
                'blockscout',
                now(),
                'gnosis'
            )
        {% endset %}

        {{ log("Inserting ABI for " ~ address, info=true) }}
        {% do run_query(insert_sql) %}
    {% else %}
        {{ log("No ABI to insert for " ~ address, info=true) }}
    {% endif %}

    -- Check if implementations array has content and appears to be an array
    {% set has_impls = implementations_array != '[]' and implementations_array != '' %}

    -- If this is a proxy contract with implementations
    {% if has_impls %}
        {{ log("Contract has implementations, extracting addresses using direct blockscout query", info=true) }}

        -- First run a command to enable JSON type support
        {% set enable_json_sql %}
            SET allow_experimental_json_type = 1
        {% endset %}

        {{ log("Enabling JSON type support", info=true) }}
        {% do run_query(enable_json_sql) %}

        -- Now extract implementation data in a separate query
        {% set extract_impl_query %}
            WITH src AS (
                SELECT body 
                FROM url(
                    'https://gnosis.blockscout.com/api/v2/smart-contracts/{{ address | lower }}',
                    'Raw',
                    'body String'
                )
            ),
            data AS (
                SELECT 
                    JSONExtractArrayRaw(body, 'implementations') AS implementations
                FROM src
            )
            SELECT
                JSONExtractString(implementations[1], 'address_hash') AS impl_address,
                JSONExtractString(implementations[1], 'name') AS impl_name
            FROM data
        {% endset %}

        {{ log("Executing implementation extraction query", info=true) }}
        {% set impl_result = run_query(extract_impl_query) %}

        {% if impl_result.rows | length > 0 %}
            {% set impl_address = impl_result[0][0] %}
            {% set impl_name = impl_result[0][1] %}

            {{ log("Found implementation " ~ impl_address ~ " with name " ~ impl_name, info=true) }}

            -- Fetch the implementation contract ABI
            {% set impl_data = fetch_abi_from_blockscout(impl_address) %}
            {% set impl_abi_json = impl_data['abi_json'] %}

            {% if impl_abi_json and impl_abi_json != '[]' and impl_abi_json != '{}' %}
                -- Escape single quotes for ClickHouse VALUES syntax
                {% set impl_abi_safe = impl_abi_json | replace("'", "\\'") %}

                -- Check if this implementation entry already exists
                {% set check_impl_sql %}
                    SELECT count(*) as cnt
                    FROM contracts_abi
                    WHERE contract_address = '{{ address }}'
                      AND implementation_address = '{{ impl_address }}'
                {% endset %}

                {% set impl_existing_result = run_query(check_impl_sql) %}
                {% set impl_exists = impl_existing_result.rows[0][0] > 0 %}

                {% if impl_exists %}
                    -- If exists, first delete the existing entry
                    {% set delete_impl_sql %}
                        ALTER TABLE contracts_abi 
                        DELETE WHERE contract_address = '{{ address }}' AND implementation_address = '{{ impl_address }}'
                    {% endset %}

                    {{ log("Deleting existing implementation ABI for " ~ address ~ " -> " ~ impl_address, info=true) }}
                    {% do run_query(delete_impl_sql) %}
                {% endif %}

                -- Insert the implementation ABI associated with the proxy
                {% set insert_impl_sql %}
                    INSERT INTO contracts_abi (
                        contract_address, 
                        implementation_address,
                        abi_json, 
                        contract_name,
                        source, 
                        updated_at,
                        chain
                    )
                    VALUES (
                        '{{ address }}', 
                        '{{ impl_address }}',
                        '{{ impl_abi_safe }}',
                        '{{ impl_name | replace("'", "\\'") }}',
                        'blockscout',
                        now(),
                        'gnosis'
                    )
                {% endset %}

                {{ log("Inserting implementation ABI for " ~ address ~ " -> " ~ impl_address, info=true) }}
                {% do run_query(insert_impl_sql) %}

                -- DO NOT insert the implementation as its own entry anymore
            {% else %}
                {{ log("No ABI available for implementation " ~ impl_address, info=true) }}
            {% endif %}
        {% else %}
            {{ log("No implementation found", info=true) }}
        {% endif %}
    {% else %}
        {{ log("Contract " ~ address ~ " has no implementations", info=true) }}
    {% endif %}
{% endmacro %}

macro.gnosis_dbt.decode_logs.macro_sql:
{% macro decode_logs(
        source_table,
        contract_address=null,
        contract_address_ref=null,
        contract_type_filter=null,
        abi_source_address=null,
        output_json_type=false,
        incremental_column='block_timestamp',
        address_column='address',
        start_blocktime=null,
        event_name_filter=none,
        chain='gnosis'
) %}

{# Check if using ref model (new way) or address list (old way) #}
{% if contract_address_ref %}
  {% if contract_type_filter %}
    {% set type_where = " WHERE cw.contract_type = '" ~ contract_type_filter ~ "'" %}
    {% set type_and = " AND cw.contract_type = '" ~ contract_type_filter ~ "'" %}
  {% else %}
    {% set type_where = "" %}
    {% set type_and = "" %}
  {% endif %}

  {# ----------------------------------------------------------------
     Detect whether the referenced whitelist/registry seed exposes an
     `abi_source_address` column. This column is present on proxy
     registries like `contracts_circles_registry` (where the ABI lives
     at a different address than the deployed contract) but NOT on
     simple flat whitelists like `contracts_whitelist` (used for
     UniswapV3 / Swapr V3 pools where each pool is its own contract
     with its own ABI).

     When the column is missing, fall back to using `cw.address`
     directly so the JOIN and subquery references stay valid.

     We introspect the relation at compile time via the adapter; the
     `{% if execute %}` guard means this no-ops at parse time and only
     runs once the model is actually being built.
     ---------------------------------------------------------------- #}
  {% set has_abi_source_col = false %}
  {% if execute %}
    {% set _cw_columns = adapter.get_columns_in_relation(contract_address_ref) %}
    {% set _cw_column_names = _cw_columns | map(attribute='name') | map('lower') | list %}
    {% if 'abi_source_address' in _cw_column_names %}
      {% set has_abi_source_col = true %}
    {% endif %}
  {% endif %}

  {% set addr_filter = "lower(replaceAll(" ~ address_column ~ ", '0x', '')) IN (SELECT lower(replaceAll(cw.address, '0x', '')) FROM " ~ contract_address_ref ~ " cw" ~ type_where ~ ")" %}
  {% if abi_source_address %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') = '" ~ (abi_source_address | lower | replace('0x', '') | trim) ~ "'" %}
  {% elif has_abi_source_col %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') IN (SELECT lower(replaceAll(coalesce(nullIf(cw.abi_source_address, ''), cw.address), '0x', '')) FROM " ~ contract_address_ref ~ " cw" ~ type_where ~ ")" %}
  {% else %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') IN (SELECT lower(replaceAll(cw.address, '0x', '')) FROM " ~ contract_address_ref ~ " cw" ~ type_where ~ ")" %}
  {% endif %}
{% else %}
  {# EXISTING: Original logic - works exactly as before #}
  {# — Normalize contract_address to list — #}
  {% if contract_address is string %}
    {% set addr_list = [contract_address] %}
  {% else %}
    {% set addr_list = contract_address %}
  {% endif %}

  {# — Normalize addresses (remove 0x, lowercase, trim) — #}
  {% set normalized = [] %}
  {% for addr in addr_list %}
    {% set normalized_addr = addr | lower | replace('0x', '') | trim %}
    {% set _ = normalized.append(normalized_addr) %}
  {% endfor %}

  {# — Build address filter for WHERE clause — #}
  {% if normalized | length > 1 %}
    {# Multiple addresses: use IN clause #}
    {% set addr_quoted = [] %}
    {% for addr in normalized %}
      {% set _ = addr_quoted.append("'" ~ addr ~ "'") %}
    {% endfor %}
    {% set addr_filter = "lower(replaceAll(" ~ address_column ~ ", '0x', '')) IN (" ~ addr_quoted | join(', ') ~ ")" %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') IN (" ~ addr_quoted | join(', ') ~ ")" %}
  {% else %}
    {# Single address: use equality (backward compatible) #}
    {% set addr = normalized[0] %}
    {% set addr_filter = address_column ~ " = '" ~ addr ~ "'" %}
    {% set abi_filter = "replaceAll(lower(contract_address),'0x','') = '" ~ addr ~ "'" %}
  {% endif %}
{% endif %}

{# — pull in the ABI for this contract(s) — #}
{% set sig_sql %}
SELECT
  replaceAll(lower(contract_address), '0x', '')          AS abi_contract_address,
  replace(signature,'0x','')                     AS topic0_sig,
  event_name,
  arrayMap(x->JSONExtractString(x,'name'),
           JSONExtractArrayRaw(params))          AS names,
  arrayMap(x->JSONExtractString(x,'type'),
           JSONExtractArrayRaw(params))          AS types,
  arrayMap(x->JSONExtractBool(x,'indexed'),
           JSONExtractArrayRaw(params))          AS flags
FROM {{ ref('event_signatures') }}
WHERE chain = '{{ chain }}'
  AND {{ abi_filter }}
{% endset %}

{# — Optional pre-decode topic0 filter — #}
{# When event_name_filter is supplied, resolve those event names to their
   topic0 signatures from the event_signatures seed and push the filter into
   the logs CTE *before* the dedup window and the decode arrayMaps. This avoids
   decoding every log just to keep a few rare event types. #}
{% set topic0_filter = "" %}
{% if event_name_filter %}
  {% set ev_quoted = [] %}
  {% for ev in event_name_filter %}
    {% set _ = ev_quoted.append("'" ~ ev ~ "'") %}
  {% endfor %}
  {% set topic0_filter = "AND replaceAll(lower(topic0),'0x','') IN (SELECT replaceAll(lower(signature),'0x','') FROM " ~ ref('event_signatures') ~ " WHERE chain = '" ~ chain ~ "' AND event_name IN (" ~ ev_quoted | join(', ') ~ "))" %}
{% endif %}

{% set sql_body %}
{% set start_month = var('start_month', none) %}
{% set end_month   = var('end_month', none) %}
{% set incr_end    = mb_var('incremental_end_date') %}

WITH

logs AS (
  SELECT * FROM (
    SELECT *,
      row_number() OVER (
        PARTITION BY block_number, transaction_index, log_index
        ORDER BY insert_version DESC
      ) AS _dedup_rn
    FROM {{ source_table }}
    WHERE {{ addr_filter }}

      {% if topic0_filter %}
        {{ topic0_filter }}
      {% endif %}

      {% if start_blocktime is not none and start_blocktime|trim != '' %}
        AND {{ incremental_column }} >= toDateTime('{{ start_blocktime }}')
      {% endif %}

      {# Batch window filter: used by refresh.py for batched full refresh #}
      {% if start_month is not none and end_month is not none %}
        AND {{ incremental_column }} >= toDateTime('{{ start_month }}')
        AND {{ incremental_column }} <  toDateTime('{{ end_month }}') + INTERVAL 1 MONTH
      {% endif %}

      {# Daily no-overlap watermark. block_number is strictly monotonic and
         immutable, so `> max(block_number)` appends each block exactly once
         with no anti-join (memory-light) and no shared-timestamp boundary
         that block_timestamp would hit. Reorg/late corrections go through a
         targeted --full-refresh, never the daily path.

         The watermark is fetched at render time and embedded as LITERALS:
         a scalar subquery on block_number cannot prune partitions, forcing
         every run to read the address column across the full table span
         (measured 112s/run vs 9s with literal bounds). The extra literal
         `{{ incremental_column }} >= <ts of last block>` is what enables
         partition pruning; it is provably safe because the strict
         block_number bound already excludes everything at or before the
         watermark. Empty/missing target => no watermark (same as before).

         is_incremental() guard: the watermark only makes sense when dbt is
         appending to an existing incremental target. For table-materialized
         callers (e.g. the Celo native models that full-rebuild while the
         backfill is in flight) it would read the OLD table's max block and
         wrongly exclude everything before it from the rebuild; on an
         incremental model's very first build it made run_query fail on the
         missing target. Both cases now skip the watermark; established
         incremental runs compile byte-identically. #}
      {% if incremental_column and not flags.FULL_REFRESH and is_incremental() %}
        {% set _wm_bn = none %}{% set _wm_ts = none %}
        {% if execute %}
          {% set _wm = run_query("SELECT max(block_number), toString(max(" ~ incremental_column ~ ")) FROM " ~ this) %}
          {% set _wm_bn = _wm.columns[0].values()[0] %}
          {% set _wm_ts = _wm.columns[1].values()[0] %}
        {% endif %}
        {% if _wm_bn is not none %}
        AND block_number > {{ _wm_bn }}
        AND {{ incremental_column }} >= toDateTime('{{ _wm_ts }}')
        {% endif %}
        {# Microbatch upper bound: the runner advances incremental_end_date one
           day at a time, so each slice only reads that day's new blocks. This
           lets a model that's far behind catch up in bounded, low-memory slices
           instead of one giant backlog read. No-op on the plain daily path. #}
        {% if incr_end is not none %}
          AND toDate({{ incremental_column }}) <= toDate('{{ incr_end }}')
        {% endif %}
      {% endif %}
  )
  WHERE _dedup_rn = 1
),

{% if contract_address_ref %}
logs_with_abi AS (
  SELECT
    l.*,
    {% if abi_source_address %}
    '{{ abi_source_address | lower | replace('0x', '') | trim }}' AS abi_join_address
    {% elif has_abi_source_col %}
    lower(replaceAll(coalesce(nullIf(cw.abi_source_address, ''), cw.address), '0x', '')) AS abi_join_address
    {% else %}
    lower(replaceAll(cw.address, '0x', '')) AS abi_join_address
    {% endif %}
  FROM logs l
  ANY LEFT JOIN {{ contract_address_ref }} cw
    ON lower(replaceAll(l.{{ address_column }}, '0x', '')) = lower(replaceAll(cw.address, '0x', ''))
    {{ type_and }}
),
{% else %}
logs_with_abi AS (
  SELECT
    l.*,
    lower(replaceAll(l.{{ address_column }}, '0x', '')) AS abi_join_address
  FROM logs l
),
{% endif %}

abi AS ( {{ sig_sql }} ),

process AS (
  SELECT
    l.block_number,
    l.block_timestamp,
    l.transaction_hash,
    l.transaction_index,
    l.log_index,
    l.address           AS contract_address,
    a.event_name,

    -- ABI arrays
    a.names             AS param_names,
    a.types             AS param_types,
    a.flags             AS param_flags,
    length(a.types)     AS n_params,

    -- topics and data
    [l.topic1, l.topic2, l.topic3]       AS raw_topics,
    replaceAll(l.data,'0x','')           AS data_hex,

    -- non-indexed metadata (zip flags/types/positions, then filter non-indexed)
    arrayFilter((f,t,i) -> not f,
      arrayZip(a.flags, a.types, range(n_params))
    )                                    AS ni_meta,

    arrayMap(x -> x.2, ni_meta)          AS ni_types,
    arrayMap(x -> x.3, ni_meta)          AS ni_positions,

    -- head words (32-byte) from start of the data head area
    arrayMap(i ->
      if(i*64 < length(data_hex),
         substring(data_hex, 1 + i*64, 64),
         NULL),
      range(greatest(length(ni_types), 1) * 16)  -- generous upper bound
    )                                    AS data_words,

    -- base type for arrays (strip [])
    arrayMap(j -> replaceRegexpOne(ni_types[j+1], '\\[\\]$', ''), range(length(ni_types))) AS ni_base_types,

    /* ===================== DECODING ====================== */
    -- For each non-indexed param j return a STRING:
    --  - Arrays -> toJSONString(Array(String))
    --  - Dynamic scalars -> String (hex or utf8)
    --  - Static scalars -> String
    arrayMap(j ->
      if(
        /* -------- ARRAY TYPES -------- */
        endsWith(ni_types[j+1],'[]'),

        /* Build JSON string of the fully decoded array */
        toJSONString(
          arrayMap(
            k ->
              multiIf(
                ni_base_types[j+1] = 'address',
                  concat(
                    '0x',
                    substring(
                      substring(
                        data_hex,
                        1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2,
                        64 + 64 + (k + 1) * 64
                      ),
                      (64 + k*64) + 25, 40
                    )
                  ),

                ni_base_types[j+1] = 'bytes32',
                  concat(
                    '0x',
                    substring(
                      data_hex,
                      1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2 + 64 + k*64,
                      64
                    )
                  ),

                startsWith(ni_base_types[j+1], 'uint')
                OR ni_base_types[j+1] = 'bool',
                  /* bool is stored as a 0/1 uint256 word, so we can use
                     the same reinterpret path as uint*. Output is '0' or
                     '1' (decimal string). */
                  toString(
                    reinterpretAsUInt256(
                      reverse(
                        unhex(
                          substring(
                            data_hex,
                            1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2 + 64 + k*64,
                            64
                          )
                        )
                      )
                    )
                  ),

                  startsWith(ni_base_types[j+1], 'int'),
                  toString(
                    reinterpretAsInt256(
                      reverse(
                        unhex(
                          substring(
                            data_hex,
                            1 + toUInt32(reinterpretAsInt256(reverse(unhex(data_words[j+1])))) * 2 + 64 + k*64,
                            64
                          )
                        )
                      )
                    )
                  ),

                /* Fallback: full 32-byte hex */
                concat(
                  '0x',
                  substring(
                    data_hex,
                    1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2 + 64 + k*64,
                    64
                  )
                )
              ),
            /* range(N) where N is array length at base */
            range(
              toUInt32(
                reinterpretAsUInt256(
                  reverse(
                    unhex(
                      substring(
                        data_hex,
                        1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2,
                        64
                      )
                    )
                  )
                )
              )
            )
          )
        ),

        /* -------- DYNAMIC SCALARS (string/bytes/bytesN≠32) -------- */
        if(
          ni_types[j+1] = 'bytes'
          OR ni_types[j+1] = 'string'
          OR (startsWith(ni_types[j+1],'bytes') AND ni_types[j+1] != 'bytes32'),

          /* payload = hex of exactly len bytes; strings converted later */
          substring(
            data_hex,
            1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2 + 64,
            toUInt32(
              reinterpretAsUInt256(
                reverse(
                  unhex(
                    substring(
                      data_hex,
                      1 + toUInt32(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))) * 2,
                      64
                    )
                  )
                )
              )
            ) * 2
          ),

          /* -------- STATIC SCALARS -------- */
          if(
            data_words[j+1] IS NOT NULL,
            multiIf(
              ni_types[j+1] = 'bytes32',
                concat('0x', data_words[j+1]),

              ni_types[j+1] = 'address',
                concat('0x', substring(data_words[j+1], 25, 40)),

              startsWith(ni_types[j+1],'uint')
              OR ni_types[j+1] = 'bool',
                /* bool is stored as a 0/1 uint256 word — same decode path
                   as uint*. Output is '0' or '1' (decimal string). */
                toString(reinterpretAsUInt256(reverse(unhex(data_words[j+1])))),

              startsWith(ni_types[j+1],'int'),
                toString(reinterpretAsInt256(reverse(unhex(data_words[j+1])))),

              NULL
            ),
            NULL
          )
        )
      ),
      range(length(ni_types))
    ) AS raw_values_str,

    -- Human-friendly normalization to STRING:
    -- - Arrays already JSON strings: pass through
    -- - Strings: hex → utf8 (remove NULs)
    -- - Bytes/bytesN: ensure 0x prefix
    arrayMap(j ->
      multiIf(
        endsWith(ni_types[j+1],'[]') AND raw_values_str[j+1] IS NOT NULL,
          raw_values_str[j+1],

        ni_types[j+1] = 'string' AND raw_values_str[j+1] IS NOT NULL,
          replaceRegexpAll(reinterpretAsString(unhex(raw_values_str[j+1])),'\0',''),

        ((ni_types[j+1] = 'bytes') OR (startsWith(ni_types[j+1],'bytes') AND ni_types[j+1] != 'bytes32'))
          AND raw_values_str[j+1] IS NOT NULL,
          concat('0x', raw_values_str[j+1]),

        /* else */
        raw_values_str[j+1]
      ),
      range(length(ni_types))
    ) AS decoded_ni_values,

    -- positions of indexed params (0-based positions into the param list)
    arrayMap(x -> x.3,
      arrayFilter((f,t,i) -> f, arrayZip(a.flags, a.types, range(n_params)))
    ) AS indexed_positions,

    -- stitch back into full order (correct topic index using 1-based indexOf)
    arrayMap(i ->
      if(
        param_flags[i+1],
        /* k1 is 1-based; 0 means not found */
        multiIf(
          indexOf(indexed_positions, i) = 0,
            NULL,
          param_types[i+1] = 'address',
            concat(
              '0x',
              substring(
                replaceAll(arrayElement(raw_topics, indexOf(indexed_positions, i)), '0x',''),
                25, 40
              )
            ),
          startsWith(param_types[i+1],'uint')
          OR param_types[i+1] = 'bool',
            /* Indexed bool: same reinterpret path as uint*. Output '0'/'1'. */
            toString(
              reinterpretAsUInt256(
                reverse(
                  unhex(
                    replaceAll(arrayElement(raw_topics, indexOf(indexed_positions, i)), '0x','')
                  )
                )
              )
            ),
          startsWith(param_types[i+1],'int'),
            toString(
              reinterpretAsInt256(
                reverse(
                  unhex(
                    replaceAll(arrayElement(raw_topics, indexOf(indexed_positions, i)), '0x','')
                  )
                )
              )
            ),
          /* default: bytes32/topic hash as 0x + 64 hex chars */
          concat(
            '0x',
            substring(
              replaceAll(arrayElement(raw_topics, indexOf(indexed_positions, i)), '0x',''),
              1, 64
            )
          )
        ),
        /* non-indexed: pick correct decoded value */
        decoded_ni_values[indexOf(ni_positions, i)]
      ),
      range(n_params)
    ) AS param_values,

    -- final JSON or map (all values are full strings; arrays are JSON strings)
    {% if output_json_type %}
      mapFromArrays(param_names, param_values) AS decoded_params
    {% else %}
      toJSONString(mapFromArrays(param_names, param_values)) AS decoded_params
    {% endif %}

  FROM logs_with_abi AS l
  ANY LEFT JOIN abi AS a
    ON replaceAll(l.topic0,'0x','') = a.topic0_sig
   AND l.abi_join_address = a.abi_contract_address
)

SELECT
  block_number,
  block_timestamp,
  transaction_hash,
  transaction_index,
  log_index,
  contract_address,
  event_name,
  decoded_params
FROM process
{% endset %}

{{ sql_body | trim }}
