    tags=['production', 'celo', 'gpay', 'tier3', 'api:celo_gpay_activity_by_action', 'granularity:monthly'],
    meta={
      "api": {
        "methods": ["GET"],
        "allow_unfiltered": true,
        "parameters": [
          {"name": "action", "column": "action", "operator": "=", "type": "string", "description": "Action type (Payment, Top-up, Withdrawal, Reversal)"},
          {"name": "start_date", "column": "month", "operator": ">=", "type": "date", "description": "Inclusive start date"},
          {"name": "end_date", "column": "month", "operator": "<=", "type": "date", "description": "Inclusive end date"}
        ],
        "sort": [{"column": "month", "direction": "DESC"}]
      }
    }
  )
}}

SELECT
    month,
    action,
    sum(activity_count)                  AS activity_count,
    round(toFloat64(sum(volume_usd)), 2) AS volume_usd,
    round(toFloat64(sum(volume)), 6)     AS volume_native
FROM {{ ref('fct_celo_gpay_actions_by_token_monthly') }}
GROUP BY action, month
ORDER BY month, action

